  ["_CeladonGymErikaPreBattleText"] = "Hola. Hace un\ntiempo precioso,\11¿verdad? Es tan\11agradable.\12...Vaya...\nDebo de haberme\11quedado dormida.\11Bienvenido.\12Me llamo ERIKA.\nSoy la LÍDER del\11GIMNASIO AZULONA.\12Enseño el arte\ndel arreglo floral.\11Mis POKéMON son\11de tipo planta.\12Ah, perdona, no\ntenía ni idea de\11que querías\11retarme.\12Muy bien, pero no\npienso perder.{DONE}",
  ["_CeladonGymErikaReceivedRainbowBadgeText"] = "¡Oh!\nAdmito la derrota.\12Eres extraordina-\nriamente fuerte.\12Debo concederte la\nMEDALLA ARCOÍRIS.{PROMPT}",
  ["_CeladonGymRainbowBadgeInfoText"] = "La MEDALLA ARCOÍRIS\nhará que te obedez-\11can los POKéMON\11hasta nivel 50.\12También permite a\nlos POKéMON usar\11FUERZA dentro y\11fuera del combate.\12Llévate esto\ntambién.{DONE}",
  ["_CeladonGymReceivedTM21Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!{DONE}",
  ["_CeladonGymTM21NoRoomText"] = "Deberías hacer\nsitio para esto.{DONE}",
  ["_CeladonHotelBeautyText"] = "Estoy de vacacio-\nnes con mi hermano\11y mi novio.\12¡AZULONA es una\nciudad preciosa!{DONE}",
  ["_CeladonHotelGrannyText"] = "¿POKéMON? No, este\nes un hotel para\11personas.\12Estamos completos.{DONE}",
  ["_CeladonHotelSuperNerdText"] = "¿Por qué se trajo\na su hermano?{DONE}",
  ["_CeladonMansion1FClefairyText"] = "CLEFAIRY: ¡Pi\npippippi!{DONE}",
  ["_CeladonMansion1FGrannyText"] = "Mis queridos\nPOKéMON me hacen\11compañía.\12¡MEOWTH hasta trae\ndinero a casa!{DONE}",
  ["_CeladonMansion1FManagersSuiteSignText"] = "EDIFICIO AZULONA\nSuite del Gerente{DONE}",
  ["_CeladonMansion1FMeowthText"] = "MEOWTH: ¡Miau!{DONE}",
  ["_CeladonMansion1FNidoranFText"] = "NIDORAN: ¡Kya\nkyaoo!{DONE}",
  ["_CeladonMansion2FMeetingRoomSignText"] = "GAME FREAK\nSala de Reuniones{DONE}",
  ["_CeladonMansion3FDevRoomSignText"] = "GAME FREAK\nSala de Desarrollo{DONE}",
  ["_CeladonMansion3FGameDesignerCompletedDexText"] = "¡Hala! ¡Excelente!\n¡Has completado tu\11POKéDEX!\11¡Enhorabuena!\11...{DONE}",
  ["_CeladonMansion3FGameDesignerText"] = "¿Ah, sí?\12¡Soy el diseñador\ndel juego!\12¡Llenar la POKéDEX\nes difícil, pero\11no te rindas!\12¡Cuando termines,\nven a contármelo!{DONE}",
  ["_CeladonMansion3FGameProgramPCText"] = "¡Es el programa\ndel juego! ¡Tocarlo\11podría llenarlo\11de errores!{DONE}",
  ["_CeladonMansion3FGameScriptPCText"] = "¡Es el guion!\n¡Mejor no mires\11el final!{DONE}",
  ["_CeladonMansion3FGraphicArtistText"] = "¡Soy el artista\ngráfico!\11¡Te dibujé yo!{DONE}",
  ["_CeladonMansion3FPlayingGamePCText"] = "¡Alguien está\njugando en vez de\11trabajar!{DONE}",
  ["_CeladonMansion3FProgrammerText"] = "¿Yo? ¡Soy el\nprogramador!{DONE}",
  ["_CeladonMansion3FWriterText"] = "¡Yo escribí la\nhistoria! ¿A que\11ERIKA es mona?\12¡MISTY también me\ngusta mucho!\12¡Ah, y SABRINA,\nella me gusta!{DONE}",
  ["_CeladonMansionRoofHouseHikerText"] = "¡Lo sé todo sobre\nel mundo de los\11POKéMON de tu\11GAME BOY!\12¡Reúnete con tus\namigos e inter-\11cambia POKéMON!{DONE}",
  ["_CeladonMansionRoofHouseSignText"] = "¡LO SÉ TODO!{DONE}",
  ["_CeladonMart1FCurrentFloorSignText"] = "1: MOSTRADOR\n   DE ATENCIÓN{DONE}",
  ["_CeladonMart1FDirectorySignText"] = "1: MOSTRADOR\n   DE ATENCIÓN\122: MERCADO DEL\n   ENTRENADOR\123: VIDEOJUEGOS TV\124: REGALOS DEL\n   SABIO\125: FARMACIA\12AZOTEA:\nMÁQUINAS EXPENDE-\nDORAS{DONE}",
  ["_CeladonMart1FReceptionistText"] = "¡Hola! Bienvenido\na los GRANDES\11ALMACENES AZULONA.\12El panel de la\nderecha explica la\11distribución.{DONE}",
  ["_CeladonMart2FCurrentFloorSignText"] = "¡Objetos de\nprimera para\11entrenadores!\122: MERCADO DEL\n   ENTRENADOR{DONE}",
  ["_CeladonMart2FGirlText"] = "Para las salidas\nlargas, deberías\11comprar REVIVIR.{DONE}",
  ["_CeladonMart2FMiddleAgedManText"] = "El SUPERREPEL\nmantiene lejos a\11los POKéMON\11débiles...\12Mmm, ¡es un REPEL\nmás potente!{DONE}",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!{DONE}",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "¡La MT18 es\nCONTRAATAQUE!\11¡No como el que\11enseño yo en el\11mostrador, ojo!{DONE}",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "¡Tu mochila está\nllena de objetos!{DONE}",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "¡Ah, hola! ¡Por\nfin terminé\11POKéMON!\12¿Aún no has\nterminado? ¡Esto\11puede serte útil!{PROMPT}",
  ["_CeladonMart3FCurrentFloorSignText"] = "3: VIDEOJUEGOS TV{DONE}",
  ["_CeladonMart3FFightingGameText"] = "¡Un juego de\nlucha! ¡Parece\11difícil!{DONE}",
  ["_CeladonMart3FGameBoyKid1Text"] = "¡Los POKéMON\ncapturados se\11registran con un\11N.º de ID y el EO,\11el nombre del\11Entrenador\11Original que lo\11atrapó!{DONE}",
  ["_CeladonMart3FGameBoyKid2Text"] = "¡Vale!\12¡Mi colega me va a\ncambiar su\11KANGASKHAN por mi\11GRAVELER!{DONE}",
  ["_CeladonMart3FGameBoyKid3Text"] = "¡Vamos, GRAVELER!\12¡Me encanta\nGRAVELER! ¡Los\11colecciono!\12¿Eh?\12¡GRAVELER se ha\nconvertido en\11otro POKéMON!{DONE}",
  ["_CeladonMart3FLittleBoyText"] = "¡Puedes identifi-\ncar los POKéMON\11que consigues en\11intercambios por\11su N.º de ID!{DONE}",
  ["_CeladonMart3FPokemonPosterText"] = "¡Rojo y Azul!\n¡Los dos son\11POKéMON!{DONE}",
  ["_CeladonMart3FPuzzleGameText"] = "¡Un juego de\npuzles! ¡Parece\11adictivo!{DONE}",
  ["_CeladonMart3FRPGText"] = "¡Un RPG! ¡No hay\ntiempo para eso!{DONE}",
  ["_CeladonMart3FSNESText"] = "¡Es una SNES!{DONE}",
  ["_CeladonMart3FSportsGameText"] = "¡Un juego de\ndeportes! ¡A papá\11le gustará!{DONE}",
  ["_CeladonMart4FCurrentFloorSignText"] = "¡Exprésate con\nregalos!\124: REGALOS DEL\n   SABIO\12¡Especial evolu-\nción! ¡PIEDRAs\11elementales en\11oferta!{DONE}",
  ["_CeladonMart4FSuperNerdText"] = "¡Voy a comprar\nun MUÑECO POKé\11para mi novia!{DONE}",
  ["_CeladonMart4FYoungsterText"] = "He oído algo útil.\12¡Puedes huir de\nlos POKéMON\11salvajes distra-\11yéndolos con un\11MUÑECO POKé!{DONE}",
  ["_CeladonMart5FCurrentFloorSignText"] = "5: FARMACIA{DONE}",
  ["_CeladonMart5FGentlemanText"] = "Los potenciadores\nde POKéMON solo se\11compran aquí.\12Usa CALCIO para\naumentar el ESPECIAL.\12Usa CARBOS para\naumentar la VELOCIDAD.{DONE}",
  ["_CeladonMart5FSailorText"] = "Vengo a por poten-\nciadores de POKéMON.\12¡La PROTEÍNA sube\nel ATAQUE.\12El HIERRO sube la\nDEFENSA!{DONE}",
  ["_CeladonMartRoofCurrentFloorSignText"] = "AZOTEA:\nMÁQUINAS EXPENDE-\nDORAS{DONE}",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "¡Tengo sed!\n¡Quiero algo de\11beber!\12¿Le das una\nbebida?{DONE}",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "¿Qué bebida le\ndas?{DONE}",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "¡No, gracias!\n¡Al final ya no\11tengo sed!{DONE}",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "¡Tengo sed!\n¡Quiero algo de\11beber!{DONE}",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "¡No tienes sitio\npara esto!{DONE}",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!{DONE}",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!{DONE}",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "¡{PLAYER} recibió\nla MT49!{DONE}",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\12¡{RAM:wStringBuffer} contiene\nRAYO HIELO!\12¡A veces puede\ncongelar al\11objetivo!{DONE}",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\12¡{RAM:wStringBuffer} contiene\nAVALANCHA!\12¡A veces puede\nasustar al\11objetivo!{DONE}",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\12La MT49 contiene\nTRIATAQUE!{DONE}",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "¡Bien!\12¡AGUA FRESCA!\12¡Gracias!\12¡Toma esto de mi\nparte!{DONE}",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "¡Bien!\12¡LIMONADA!\12¡Gracias!\12¡Toma esto de mi\nparte!{DONE}",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "¡Bien!\12¡REFRESCO!\12¡Gracias!\12¡Toma esto de mi\nparte!{DONE}",
  ["_CeladonMartRoofSuperNerdText"] = "Mi hermana es\nentrenadora,\11aunque no lo\11parezca.\12¡Pero es tan\ninmadura que me\11saca de quicio!{DONE}",
  ["_CeladonPokecenterBeautyText"] = "¡Vine cuesta\narriba por el\11CARRIL BICI desde\11FUCSIA!{DONE}",
  ["_CeladonPokecenterGentlemanText"] = "¡La POKé FLAUTA\ndespierta a los\11POKéMON con un\11sonido que solo\11ellos oyen!{DONE}",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "El ATAQUE de todos\ntus POKéMON sube\11un poquito.\12También te deja\nusar DESTELLO\11siempre que\11quieras.{PROMPT}",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "Los POKéMON hasta\nnivel 30 te\11obedecerán.\12¡Los de nivel\nmayor se rebelan!\12También te deja\nusar CORTE fuera\11del combate.{PROMPT}",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "¡Todos los POKéMON\nte obedecerán!{PROMPT}",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "Los POKéMON hasta\nnivel 70 te\11obedecerán.\12¡Los de nivel\nmayor se rebelan!{PROMPT}",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Las MEDALLAS solo\nlas tienen los\11entrenadores\11expertos.\12Veo que tú tienes\nal menos una.\12¡Esas MEDALLAS\nguardan secretos\11asombrosos!{PROMPT}",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Vuelve a verme\ncuando quieras.{DONE}",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Bien, veamos...\12¿Cuál de las 8\nMEDALLAS te\11describo?{DONE}",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "Los POKéMON hasta\nnivel 50 te\11obedecerán.\12¡Los de nivel\nmayor se rebelan!\12También te deja\nusar FUERZA fuera\11del combate.{PROMPT}",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DEFENSA de\ntodos tus POKéMON\11sube un poquito.\12También te deja\nusar SURF fuera\11del combate.{PROMPT}",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VELOCIDAD de\ntodos tus POKéMON\11sube un poquito.\12También te deja\nusar VUELO fuera\11del combate.{PROMPT}",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "El ESPECIAL de tus\nPOKéMON sube un\11poquito.{PROMPT}",
  ["_CeruleanCityBikeShopSign"] = "¡La hierba y las\ncuevas, pan comido!\11TIENDA DE BICIS{DONE}",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "¡Puñetazo de\nSLOWBRO!\n¡No! ¡La has\11vuelto a fastidiar!{DONE}",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "¡Vamos, SLOWBRO!\n¡Usa BOMBA SÓNICA!\11¡Venga, SLOWBRO,\11presta atención!{DONE}",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "¡SLOWBRO, RETÍRATE!\n¡No! ¡Así no!\12¡Es dificilísimo\ncontrolar a los\11POKéMON!\12¡La obediencia de\ntus POKéMON depende\11de tu talento como\11entrenador!{DONE}",
  ["_CeruleanCityCooltrainerF2Text"] = "¡Quiero una BICI\nrojo fuego!\12¡La guardaré en\ncasa para que no\11se ensucie!{DONE}",
  ["_CeruleanCityCooltrainerMText"] = "¿Tú también eres\nentrenador?\11Coleccionar,\11luchar... es una\11vida dura.{DONE}",
  ["_CeruleanCityGuardText"] = "Aquí robaron a la\ngente.\12¡Está claro que\nel TEAM ROCKET\11está detrás de\11este crimen tan\11atroz!\12¡Hasta a nuestra\nPOLICÍA le cuesta\11con los ROCKET!{DONE}",
  ["_CeruleanCityGymSign"] = "GIMNASIO POKéMON\nDE CIUDAD CELESTE\11LÍDER: MISTY\12¡La sirena\nmarimacho!{DONE}",
  ["_CeruleanCityRivalDefeatedText"] = "¡Eh!\n¡Tranqui!\11¡Ya has ganado!{PROMPT}",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: ¡Eh,\nadivina qué!\12¡Fui a casa de\nBILL y conseguí\11que me enseñara\11sus POKéMON raros!\12¡Eso añadió un\nmontón de páginas\11a mi POKéDEX!\12¡BILL es mundial-\nmente famoso como\11POKéMANÍACO!\12¡Inventó el Sistema\nde Almacén de\11POKéMON en PC!\12Como usas su\nsistema, ¡ve a\11darle las gracias!\12¡Bueno, mejor me\npongo en marcha!\11¡Nos vemos!{DONE}",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: ¡Ey!\n¡{PLAYER}!\12¿Todavía andas\npeleándote por\11aquí atrás?\12¡A mí me va genial!\n¡He atrapado un\11montón de POKéMON\11fuertes y listos!\12¡A ver, enséñame\nlo que has\11atrapado tú,\11{PLAYER}!{DONE}",
  ["_CeruleanCityRivalVictoryText"] = "¡Je!\n¡No eres rival\11para mi genio!{PROMPT}",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\12¡Mejor me pongo\nen marcha! ¡Adiós!{DONE}",
  ["_CeruleanCityRocketIGiveUpText"] = "¡Para!\n¡Me rindo! ¡Me\11iré sin armar\11jaleo!{PROMPT}",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "¡Vale! ¡Devolveré\nla MT que robé!{PROMPT}",
  ["_CeruleanCityRocketReceivedTM28Text"] = "¡{PLAYER} recuperó\nla MT28!{DONE}",
  ["_CeruleanCityRocketTM28NoRoomText"] = "¡Haz sitio para\nesto!\12¡No puedo huir\nhasta que te lo\11dé!{DONE}",
  ["_CeruleanCityRocketText"] = "¡Eh! ¡Fuera de\naquí!\n¡Este no es tu\11jardín! ¿Eh? ¿Yo?\12¡Soy un simple\ntestigo inocente!\11¿No me crees?{DONE}",
  ["_CeruleanCitySignText"] = "CIUDAD CELESTE\nUn aura azul y\11misteriosa la\11envuelve{DONE}",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO\nignoró las órdenes...{DONE}",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO está\nholgazaneando...{DONE}",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO se echó\nuna cabezadita...{DONE}",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO miró\npara otro lado...{DONE}",
  ["_CeruleanCitySuperNerd1Text"] = "Ese arbusto de\ndelante de la\11tienda estorba.\12A lo mejor hay un\ncamino para\11rodearlo.{DONE}",
  ["_CeruleanCitySuperNerd2Text"] = "¿Estás haciendo\nuna enciclopedia\11sobre POKéMON?\11Suena entretenido.{DONE}",
  ["_CeruleanCitySuperNerd3Text"] = "¡Esta es la CUEVA\nCELESTE! ¡Dentro\11viven POKéMON\11terriblemente\11fuertes!\12¡Solo el campeón\nde la LIGA POKéMON\11tiene permitido\11entrar!{DONE}",
  ["_CeruleanCityTrainerTipsText"] = "CONSEJOS\12Pulsar el Botón B\ndurante una\11evolución cancela\11todo el proceso.{DONE}",
  ["_CeruleanGymAfterBattleText1"] = "Tienes que\nenfrentarte a\11otros entrenadores\11para saber lo\11bueno que eres de\11verdad.{DONE}",
  ["_CeruleanGymAfterBattleText2"] = "¡MISTY va a seguir\nmejorando!\12¡No perderá contra\nalguien como tú!{DONE}",
  ["_CeruleanGymBattleText1"] = "¡Yo soy más que\nsuficiente para\11ti!\12¡MISTY puede\nesperar!{DONE}",
  ["_CeruleanGymBattleText2"] = "¡Chof!\12¡Yo primero!\n¡Vamos allá!{DONE}",
  ["_CeruleanGymEndBattleText1"] = "¡Me has\narrasado!{PROMPT}",
  ["_CeruleanGymEndBattleText2"] = "¡No\npuede ser!{PROMPT}",
  ["_CeruleanGymGymGuideBeatMistyText"] = "¡Has ganado a\nMISTY! ¿Qué te\11dije?\12¡Tú y yo, chaval,\nhacemos un equipo\11de miedo!{DONE}",
  ["_CeruleanGymGymGuideChampInMakingText"] = "¡Eh! ¡Futuro\ncampeón!\12¡Aquí va mi\nconsejo!\12¡La LÍDER, MISTY,\nes una profesional\11que usa POKéMON\11de agua!\12¡Puedes secarles\ntoda el agua con\11POKéMON de planta!\12¡O achicharrarlos\ncon electricidad!{DONE}",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "¡La MEDALLA CASCADA\nhace que te\11obedezcan todos\11los POKéMON hasta\11nivel 30!\12¡Incluidos los\nde fuera!\12¡Hay más: ahora\npuedes usar CORTE\11siempre que\11quieras!\12¡Puedes CORTAR\narbustos pequeños\11para abrir nuevos\11caminos!\12¡Y también puedes\nquedarte mi MT\11favorita!{DONE}",
  ["_CeruleanGymMistyPreBattleText"] = "¡Hola, cara nueva!\12¡Los entrenadores\nque quieren hacerse\11profesionales tienen\11que tener una\11filosofía sobre\11los POKéMON!\12¿Cuál es tu enfoque\ncuando atrapas\11POKéMON?\12¡El mío es la\nofensiva total con\11POKéMON de tipo\11agua!{DONE}",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "¡Hala!\n¡Eres demasiado!\12¡De acuerdo!\12¡Puedes quedarte\nla MEDALLA CASCADA\11para demostrar que\11me venciste!{DONE}",
  ["_CeruleanGymMistyReceivedTM11Text"] = "¡{PLAYER} recibió\nla MT11!{DONE}",
  ["_CeruleanGymMistyTM11ExplanationText"] = "¡La MT11 enseña\nRAYO BURBUJA!\12¡Úsala en un\nPOKéMON acuático!{DONE}",
  ["_CeruleanGymMistyTM11NoRoomText"] = "¡Más te vale hacer\nsitio para esto!{DONE}",
  ["_CeruleanMartCooltrainerFText"] = "¿Has visto algún\nCARAMELO RARO?\12¡Se supone que\nsube un nivel al\11POKéMON!{DONE}",
  ["_CeruleanMartCooltrainerMText"] = "Usa REPEL para\nmantener lejos a\11los bichos y a los\11POKéMON débiles.\12¡Pon a tu POKéMON\nmás fuerte el\11primero de la\11lista para mejores\11resultados!{DONE}",
  ["_CeruleanPokecenterGentlemanText"] = "¿Has oído hablar\nde BILL?\12¡Todos lo llaman\nPOKéMANÍACO!\12Aunque yo creo\nque la gente solo\11tiene envidia de\11BILL.\12¿Quién no querría\npresumir de sus\11POKéMON?{DONE}",
  ["_CeruleanPokecenterGuyText"] = "¡BILL tiene\nmuchísimos POKéMON!\12¡También colecciona\nlos raros!{DONE}",
  ["_CeruleanPokecenterSuperNerdText"] = "¡Ese BILL!\12¡He oído que\nhace lo que sea\11con tal de\11conseguir POKéMON\11raros!{DONE}",
  ["_CeruleanTradeHouseGrannyText"] = "A mi marido le\ngusta intercambiar\11POKéMON.\12Si eres colec-\ncionista, ¿te\11importaría hacer\11un cambio con él?{DONE}",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "¡Esos miserables\nROCKET!\12¡Mira lo que han\nhecho aquí!\12¡Robaron una MT\npara enseñar a\11los POKéMON a\11CAVAR agujeros!\12¡Y me costó un\ndineral, oye!{DONE}",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "¡Lo perdido,\nperdido está!\12¡He decidido\nenseñar a DIGLETT\11a CAVAR sin MT!{DONE}",
  ["_CeruleanTrashedHouseGirlText"] = "¡El TEAM ROCKET\ndebe de estar\11CAVANDO para\11tramar algo malo!{DONE}",
  ["_CeruleanTrashedHouseWallHoleText"] = "¡El TEAM ROCKET\ndejó una salida!{DONE}",
  ["_ChampionsRoomOakComeWithMeText"] = "OAK: ¡{PLAYER}!\12¡Entiendes que tu\nvictoria no fue\11solo cosa tuya!\12¡El vínculo que\ncompartes con tus\11POKéMON es\11maravilloso!\12¡{PLAYER}!\n¡Ven conmigo!{DONE}",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: ¡Así que has\nganado!\11¡Enhorabuena!\11¡Eres el nuevo\11campeón de la\11LIGA POKéMON!\12¡Cuánto has\ncrecido desde que\11partiste con\11{RAM:wNameBuffer}!\12¡{PLAYER}, te has\nhecho mayor!{DONE}",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: ¡{RIVAL}! ¡Qué\ndecepción!\12¡Vine al oír que\nhabías ganado al\11ALTO MANDO!\12¡Pero al llegar\nya habías\11perdido!\12¡{RIVAL}! ¿Entiendes\npor qué has\11perdido?\12¡Has olvidado\ntratar a tus\11POKéMON con\11confianza y cariño!\12¡Sin ellos, nunca\nvolverás a ser\11campeón!{DONE}",
  ["_ChampionsRoomOakText"] = "OAK: ¡{PLAYER}!{DONE}",
  ["_ChampionsRoomRivalAfterBattleText"] = "¿Por qué?\n¿Por qué he\11perdido?\12Nunca cometí\nningún error al\11criar mis\11POKéMON...\12¡Maldita sea!\n¡Eres el nuevo\11campeón de la\11LIGA POKéMON!\12Aunque no me guste\nadmitirlo.{DONE}",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: ¡Eh!\12¡Tenía ganas de\nverte, {PLAYER}!\12¡Mi rival tiene\nque ser fuerte\11para mantenerme\11en forma!\12¡Mientras hacía\nla POKéDEX,\11busqué por todas\11partes POKéMON\11poderosos!\12¡Y no solo eso:\nreuní equipos\11capaces de vencer\11a cualquier tipo!\12¡Y ahora!\12¡Soy el campeón\nde la LIGA POKéMON!\12¡{PLAYER}! ¿Sabes\nlo que eso\11significa?\12¡Te lo diré!\12¡Soy el entrenador\nmás poderoso del\11mundo!{DONE}",
  ["_ChanseyDexEntry"] = "POKéMON raro y\nesquivo que, se\ndice, trae la\12felicidad a quienes\nlogran hacerse con\nuno",
  ["_ChargeMoveEffectText"] = "{USER}{DONE}",
  ["_CharizardDexEntry"] = "Escupe un fuego tan\nardiente que funde\nlas rocas.\12A veces provoca\nincendios forestales\nsin querer",
  ["_CharmanderDexEntry"] = "Prefiere los luga-\nres cálidos. Se\ndice que, si llueve,\12le sale vapor de la\npunta de la cola",
  ["_CharmeleonDexEntry"] = "Cuando agita su\ncola llameante,\neleva la\12temperatura hasta\nniveles\ninsoportables",
  ["_ChooseABoxText"] = "Elige una\nCAJA <PK><MN>.{DONE}",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "¡LLAMARADA es la\ntécnica de fuego\11definitiva!\12¡No la malgastes\ncon POKéMON de\11agua!{DONE}",
  ["_CinnabarGymBlainePreBattleText"] = "¡Ja!\12¡Soy BLAINE! ¡El\nLÍDER del GIMNASIO\11CANELA!\12¡Mis POKéMON de\nfuego calcinarán\11a todos los\11retadores!\12¡Ja! ¡Más te vale\ntener ANTIQUEMAR!{DONE}",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!{DONE}",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "¡Me he\nconsumido!\12¡Te has ganado la\nMEDALLA VOLCÁNICA!{DONE}",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\12¡La MT38 contiene\nLLAMARADA!\12¡Enséñasela a\nPOKéMON de tipo\11fuego!\12¡CHARMELEON o\nPONYTA serían\11buenas opciones!{DONE}",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "¡Haz sitio para\nmi regalo!{DONE}",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "¡Ja!\12¡La MEDALLA\nVOLCÁNICA aumenta\11el ESPECIAL de\11tus POKéMON!\12¡Toma, quédate\nesto también!{DONE}",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "¡{PLAYER}! ¡Le\nhas ganado a ese\11fogonazo!{DONE}",
  ["_CinnabarGymGymGuideChampInMakingText"] = "¡Eh! ¡Futuro\ncampeón!\12¡El impulsivo\nBLAINE es un\11profesional del\11POKéMON de fuego!\12¡Apágale los\nánecos con agua!\12¡Más te vale\nllevar ANTIQUEMAR!{DONE}",
  ["_CinnabarGymQuizCorrectText"] = "¡Totalmente\ncorrecto!\12¡Pasa!{DONE}",
  ["_CinnabarGymQuizIncorrectText"] = "¡Lo siento! ¡Mala\nrespuesta!{PROMPT}",
  ["_CinnabarGymQuizIntroText"] = "¡Concurso POKéMON!\12¡Acierta y la\npuerta a la\11siguiente sala se\11abre!\12¡Falla y te\nenfrentarás a un\11entrenador!\12Si quieres\nconservar tus\11POKéMON para el\11LÍDER...\12¡Entonces acierta!\n¡Allá vamos!{PROMPT}",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "El fuego, o para\nser más preciso,\11la combustión...\12Bla, bla, bla,\nbla...{DONE}",
  ["_CinnabarGymSuperNerd1BattleText"] = "¿Sabes lo\ncaliente que\11puede llegar el\11aliento de fuego\11de un POKéMON?{DONE}",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "¡Ay!\n¡Quema, quema,\11quema!{PROMPT}",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "¡No puedo evitar\nrobar los POKéMON\11de los demás!{DONE}",
  ["_CinnabarGymSuperNerd2BattleText"] = "¡Era un ladrón,\npero me hice\11honrado como\11entrenador!{DONE}",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "¡Me\nrindo!{PROMPT}",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "¡Mis teorías son\ndemasiado\11complejas para ti!{DONE}",
  ["_CinnabarGymSuperNerd3BattleText"] = "¡No puedes ganar!\n¡He estudiado los\11POKéMON a fondo!{DONE}",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "¡Buah!\n¡Mis estudios!{PROMPT}",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "¡Ojalá hubiera un\nPOKéMON ladrón!\11¡Lo usaría!{DONE}",
  ["_CinnabarGymSuperNerd4BattleText"] = "¡Es que me gusta\nusar POKéMON de\11fuego!{DONE}",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "¡Demasiado\ncaliente!{PROMPT}",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "BLAINE se perdió\nen las montañas\11cuando apareció\11un POKéMON pájaro\11de fuego.\12¡Su luz le\npermitió a BLAINE\11encontrar el\11camino de bajada!{DONE}",
  ["_CinnabarGymSuperNerd5BattleText"] = "¡Yo sé por qué\nBLAINE se hizo\11entrenador!{DONE}",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "¡Ay!{PROMPT}",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "¡A los fans del\nPOKéMON de fuego\11nos gustan PONYTA\11y NINETALES!{DONE}",
  ["_CinnabarGymSuperNerd6BattleText"] = "¡He estado en\nmuchos GIMNASIOS,\11pero este es mi\11favorito!{DONE}",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "¡Aaay!\n¡Demasiado calor!{PROMPT}",
  ["_CinnabarGymSuperNerd7AfterBattleText"] = "¡El agua vence al\nfuego! ¡Pero el\11fuego funde a los\11POKéMON de hielo!{DONE}",
  ["_CinnabarGymSuperNerd7BattleText"] = "¡El fuego es\ndébil contra el\11H2O!{DONE}",
  ["_CinnabarGymSuperNerd7EndBattleText"] = "¡Oh!\n¡Apagado!{PROMPT}",
  ["_CinnabarIslandDoorIsLockedText"] = "La puerta está\ncerrada con llave...{DONE}",
  ["_CinnabarIslandGamblerText"] = "Los científicos\nhacen experimentos\11en el edificio\11calcinado.{DONE}",
  ["_CinnabarIslandGirlText"] = "BLAINE, del\nGIMNASIO CANELA,\11es un tipo raro\11que lleva décadas\11viviendo aquí.{DONE}",
  ["_CinnabarIslandGymSignText"] = "GIMNASIO POKéMON\nDE ISLA CANELA\11LÍDER: BLAINE\12¡El impulsivo\nmaestro del\nconcurso!{DONE}",
  ["_CinnabarIslandPokemonLabSignText"] = "LABORATORIO POKéMON{DONE}",
  ["_CinnabarIslandSignText"] = "ISLA CANELA\nLa ardiente ciudad\11del deseo abrasador{DONE}",
  ["_CinnabarLabFishingGuruText"] = "Aquí estudiamos\nlos POKéMON a\11fondo.\12La gente suele\ntraernos POKéMON\11raros para\11examinarlos.{DONE}",
  ["_CinnabarLabFossilRoomScientist1ComeAgainText"] = "¡Aiyá! ¡Ya has\nvuelto!{DONE}",
  ["_CinnabarLabFossilRoomScientist1FossilIsBackToLifeText"] = "¿Dónde estabas?\12¡Tu fósil ha\nvuelto a la vida!\12¡Era {RAM:wStringBuffer}\ncomo yo pensar!{PROMPT}",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText"] = "¡Yo tardar un\npoco!\12¡Tú ir a dar\npaseo un rato!{DONE}",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText2"] = "¡Yo tardar un\npoco!\12¡Tú ir a dar\npaseo un rato!{DONE}",
  ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "¡No! ¡Qué\nlástima!{DONE}",
  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "¡Oh! ¡Eso ser\n{RAM:wNameBuffer}!\12¡Ser fósil de\n{RAM:wStringBuffer}, un\11POKéMON ya\11extinto!\12¡Mi Máquina de\nResurrección hacer\11que ese POKéMON\11volver a vivir!{DONE}",
  ["_CinnabarLabFossilRoomScientist1TakesFossilText"] = "¡Vamos! ¡Deprisa,\ndámelo!\12¡{PLAYER} entregó\n{RAM:wNameBuffer}!{PROMPT}",
  ["_CinnabarLabFossilRoomScientist1Text"] = "¡Hola!\12¡Yo ser doctor\nimportante!\12¡Yo estudiar aquí\nfósiles raros de\11POKéMON!\12¡Tú! ¿Tener un\nfósil para mí?{PROMPT}",
  ["_CinnabarLabMeetingRoomSignText"] = "LABORATORIO POKéMON\nSala de Reuniones{DONE}",
  ["_CinnabarLabMetronomeRoomAmberPipeText"] = "¡Una tubería de\námbar!{DONE}",
  ["_CinnabarLabMetronomeRoomPCText"] = "¡Hay un correo\nelectrónico!\12...\12Los 3 POKéMON\npájaro legendarios\11son ARTICUNO,\11ZAPDOS y MOLTRES.\12Se desconoce su\nparadero.\12Planeamos explorar\nla cueva cercana\11a CELESTE.\12De: EQUIPO DE\nINVESTIGACIÓN\11POKéMON\12...{DONE}",
  ["_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text"] = "¡{PLAYER} recibió \n{RAM:wStringBuffer}!{DONE}",
  ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "¡Tic, tac, tic!\n¡Es el sonido de\11un METRÓNOMO!\12¡Retuerce el\ncerebro de tu\11POKéMON para que\11use ataques que\11no conoce!{DONE}",
  ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "¡Tu mochila está\na reventar!{DONE}",
