  ["_CinnabarLabMetronomeRoomScientist2Text"] = "EEVEE puede\nevolucionar a 1\11de 3 clases de\11POKéMON.{DONE}",
  ["_CinnabarLabPhotoText"] = "¡Una foto del\nfundador del\11LABORATORIO,\11el DR. FUJI!{DONE}",
