  ["_CinnabarLabTestingRoomSignText"] = "LABORATORIO POKéMON\nSala de Pruebas{DONE}",
  ["_CinnabarLabTradeRoomSuperNerdText"] = "¡Encontré este\nfósil tan extraño\11en MONTE MOON!\12¡Creo que es un\nPOKéMON prehistó-\11rico y raro!{DONE}",
  ["_CinnabarMartScientistText"] = "¡Nunca está de más\ntener objetos de\11sobra!{DONE}",
  ["_CinnabarMartSilphWorkerFText"] = "¿No tienen ATAQUE\nX? ¡Va bien para\11los combates!{DONE}",
  ["_CinnabarPokecenterCooltrainerFText"] = "Puedes cancelar la\nevolución.\12Cuando un POKéMON\nesté evolucionando,\11puedes detenerlo y\11dejarlo como está.{DONE}",
  ["_CinnabarPokecenterGentlemanText"] = "¿Tienes amigos?\12Los POKéMON que\nconsigues en\11intercambios\11crecen muy rápido.\12¡Creo que merece\nla pena probar!{DONE}",
  ["_CinnabarPokecenterGuyText"] = "Los POKéMON aún\npueden aprender\11técnicas tras\11cancelar la\11evolución.\12La evolución puede\nesperar hasta que\11aprendan nuevos\11ataques.{DONE}",
  ["_CinnabarQuizQuestionsText1"] = "¿CATERPIE\nevoluciona a\11BUTTERFREE?{DONE}",
  ["_CinnabarQuizQuestionsText2"] = "¿Hay 9 MEDALLAS\noficiales de la\11LIGA POKéMON?{DONE}",
  ["_CinnabarQuizQuestionsText3"] = "¿POLIWAG\nevoluciona 3\11veces?{DONE}",
  ["_CinnabarQuizQuestionsText4"] = "¿Los ataques de\ntipo rayo son\11eficaces contra\11los POKéMON de\11tipo tierra?{DONE}",
  ["_CinnabarQuizQuestionsText5"] = "¿Dos POKéMON de\nla misma clase y\11nivel no son\11idénticos?{DONE}",
