  ["_ClearSaveDataText"] = "¿Borrar todos los\ndatos guardados?{DONE}",
  ["_ClefableDexEntry"] = "POKéMON hada tímido\nque rara vez se\ndeja ver.\12Huye y se esconde\nen cuanto nota\npresencia humana",
