  ["_CopycatsHouse1FMiddleAgedWomanText"] = "Mi hija es muy\negocéntrica.\11Solo tiene unos\11pocos amigos.{DONE}",
  ["_CopycatsHouse2FCopycatDoYouLikePokemonText"] = "{PLAYER}: ¡Hola!\n¿Te gustan los\11POKéMON?\12{PLAYER}: Eh, no,\nsolo te lo\11preguntaba.\12{PLAYER}: ¿Eh?\n¡Qué rara eres!\12IMITADORA: ¿Mmm?\n¿Que deje de\11imitar?\12¡Pero si es mi\nafición favorita!{PROMPT}",
  ["_CopycatsHouse2FCopycatReceivedTM31Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!{DONE}",
