  ["_FuchsiaBillsGrandpasHouseBillsGrandpaText"] = "¿Mmm? ¿Has\nconocido a BILL?\12¡Es mi nieto!\12¡Ya de niño le\ngustaba coleccionar\11cosas!{DONE}",
  ["_FuchsiaBillsGrandpasHouseMiddleAgedWomanText"] = "¡El GUARDA de la\nZONA SAFARI es\11mayor, pero sigue\11activo!\12Aunque todos sus\ndientes son\11postizos.{DONE}",
  ["_FuchsiaBillsGrandpasHouseYoungsterText"] = "¡BILL archiva sus\npropios datos de\11POKéMON en su PC!\12¿Te los ha\nenseñado?{DONE}",
  ["_FuchsiaCityChanseySignText"] = "Nombre: CHANSEY\12Atrapar uno es\ncuestión de suerte.{PROMPT}",
  ["_FuchsiaCityErikText"] = "ERIK: ¿Dónde está\nSARA? Dije que la\11vería aquí.{DONE}",
  ["_FuchsiaCityFossilSignKabutoText"] = "Nombre: KABUTO\12Un POKéMON\nresucitado a\11partir de un\11fósil.{PROMPT}",
  ["_FuchsiaCityFossilSignOmanyteText"] = "Nombre: OMANYTE\12Un POKéMON\nresucitado a\11partir de un\11fósil.{PROMPT}",
  ["_FuchsiaCityFossilSignUndeterminedText"] = "...{DONE}",
  ["_FuchsiaCityGamblerText"] = "La ZONA SAFARI\ntiene un zoo\11delante de la\11entrada.\12Detrás está la\nCACERÍA SAFARI\11para atrapar\11POKéMON.{DONE}",
  ["_FuchsiaCityGymSignText"] = "GIMNASIO POKéMON\nDE CIUDAD FUCSIA\11LÍDER: KOGA\12El maestro ninja\ndel veneno{DONE}",
  ["_FuchsiaCityKangaskhanSignText"] = "Nombre: KANGASKHAN\12Un POKéMON\nmaternal que cría\11a su pequeño en\11una bolsa del\11vientre.{PROMPT}",
  ["_FuchsiaCityLaprasSignText"] = "Nombre: LAPRAS\12Alias, el rey de\nlos mares.{PROMPT}",
  ["_FuchsiaCityPokecenterGuyText"] = "Si estás estudiando \nPOKéMON, visita\11la ZONA SAFARI.\12Tiene todo tipo\nde POKéMON raros.{DONE}",
  ["_FuchsiaCityPokemonText"] = "!{DONE}",
  ["_FuchsiaCitySafariGameSignText"] = "CACERÍA SAFARI\n¡ATRAPA TU POKéMON!{DONE}",
  ["_FuchsiaCitySafariZoneSignText"] = "PARAÍSO POKéMON\nZONA SAFARI{DONE}",
  ["_FuchsiaCitySignText"] = "CIUDAD FUCSIA\n¡Contempla! ¡El\11rosa de la pasión!{DONE}",
  ["_FuchsiaCitySlowpokeSignText"] = "Nombre: SLOWPOKE\12Amistoso y muy\nlento de movimientos.{PROMPT}",
