  ["_FuchsiaCityWardensHomeSignText"] = "ZONA SAFARI\nCASA DEL GUARDA{DONE}",
  ["_FuchsiaCityYoungster1Text"] = "¿Probaste la\nCACERÍA SAFARI?\11¡Algunos POKéMON\11solo se atrapan\11allí!{DONE}",
  ["_FuchsiaCityYoungster2Text"] = "Esa esfera con\nobjeto de ahí\11dentro es en\11realidad un\11POKéMON.{DONE}",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "¡Hola, {PLAYER}!\12¿Qué tal pican\nlos peces?{DONE}",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "¡Vaya!\12¡No tienes sitio\npara mi regalo!{DONE}",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "¡Grandioso! ¡Me\ngusta tu estilo!\12¡Toma esto y a\npescar, joven!\12¡{PLAYER} recibió\nuna {RAM:wStringBuffer}!{DONE}",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "¡Soy el hermano\nmayor del GURÚ DE\11LA PESCA!\12¡Me encaaanta\npescar!\12¿A ti te gusta\npescar?{DONE}",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Ay... Qué\ndecepción...{DONE}",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "¡Es asombroso\ncómo los ninjas\11siguen aterrando\11hoy en día!{DONE}",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "¡Eh! ¡Futuro\ncampeón!\12¡El GIMNASIO FUCSIA\nestá lleno de\11paredes invisibles!\12¡KOGA puede parecer\ncerca, pero está\11bloqueado!\12¡Tienes que\nencontrar huecos\11en las paredes\11para llegar a él!{DONE}",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA: ¡Fuajajaja!\12¿Un simple niño\ncomo tú se atreve\11a retarme?\12Muy bien, te\nmostraré el\11verdadero terror\11de un maestro\11ninja.\12¡Sentirás la\ndesesperación de\11las técnicas de\11veneno y sueño!{DONE}",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "¡Cuando sufren\nTÓXICO, los\11POKéMON padecen\11cada vez más a\11medida que avanza\11el combate!\12¡Aterrorizará a\ntus rivales sin\11duda!{DONE}",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "¡Bah!\n¡Has demostrado\11tu valía!\12¡Toma! ¡Llévate\nla MEDALLA ALMA!{PROMPT}",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!{DONE}",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "¡Ahora que tienes\nla MEDALLA ALMA,\11la DEFENSA de tus\11POKéMON aumenta!\12¡También te deja\nusar SURF fuera\11del combate!\12¡Ah! ¡Llévate\nesto también!{DONE}",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "\12¡La MT06 contiene\nTÓXICO!\12¡Es una técnica\nsecreta de más de\11400 años!{DONE}",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "¡Haz sitio para\nesto, niño!{DONE}",
  ["_FuchsiaGymRocker1AfterBattleText"] = "¿Así que mezclas\nmúsculo con\11cerebro?\11¡Buena estrategia!{DONE}",
  ["_FuchsiaGymRocker1BattleText"] = "¡La fuerza no es\nla clave para los\11POKéMON!\12¡Es la estrategia!\12¡Te enseñaré cómo\nla estrategia\11puede vencer a la\11fuerza bruta!{DONE}",
  ["_FuchsiaGymRocker1EndBattleText"] = "¿Qué?\n¡Extraordinario!{PROMPT}",
  ["_FuchsiaGymRocker2AfterBattleText"] = "¡Seguiré entrenando\ncon KOGA, mi\11maestro ninja!{DONE}",
  ["_FuchsiaGymRocker2BattleText"] = "¡Quería ser ninja,\nasí que me uní a\11este GIMNASIO!{DONE}",
  ["_FuchsiaGymRocker2EndBattleText"] = "¡Estoy\nacabado!{PROMPT}",
  ["_FuchsiaGymRocker3AfterBattleText"] = "¡Me gustan las\ntécnicas de veneno\11y sueño, porque\11siguen actuando\11tras el combate!{DONE}",
  ["_FuchsiaGymRocker3BattleText"] = "¡A ver si vences\nmis técnicas\11especiales!{DONE}",
  ["_FuchsiaGymRocker3EndBattleText"] = "¡Me\nhas engañado!{PROMPT}",
  ["_FuchsiaGymRocker4AfterBattleText"] = "¡Me has impresio-\nnado! ¡Aquí va\11una pista!\12¡Fíjate muy bien\nen los huecos de\11las paredes\11invisibles!{DONE}",
  ["_FuchsiaGymRocker4BattleText"] = "¡Alto ahí!\12¿Te frustran\nnuestras paredes\11invisibles?{DONE}",
  ["_FuchsiaGymRocker4EndBattleText"] = "¡Vaya!\n¡Lo ha pillado!{PROMPT}",
  ["_FuchsiaGymRocker5AfterBattleText"] = "¡Aún tengo mucho\nque aprender!{DONE}",
  ["_FuchsiaGymRocker5BattleText"] = "¡Yo también\nestudio la senda\11del ninja con el\11maestro KOGA!\12¡Los ninjas tienen\nuna larga tradición\11de usar animales!{DONE}",
  ["_FuchsiaGymRocker5EndBattleText"] = "¡Auuu!{PROMPT}",
  ["_FuchsiaGymRocker6AfterBattleText"] = "¡Donde hay luz,\nhay sombra!\12¡Luz y sombra!\n¿Cuál eliges tú?{DONE}",
  ["_FuchsiaGymRocker6BattleText"] = "¡El maestro KOGA\nviene de un largo\11linaje de ninjas!\12¿Y tú de qué\ndesciendes?{DONE}",
  ["_FuchsiaGymRocker6EndBattleText"] = "¡Se me han caído\nlas esferas!{PROMPT}",
  ["_FuchsiaMartCooltrainerFText"] = "¿Probaste VELOCIDAD\nX? ¡Acelera a un\11POKéMON en combate!{DONE}",
