  ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "Al GUARDA le\npusimos el mote\11de SLOWPOKE.\12¡Los dos parecen\nigual de pasmados!{DONE}",
  ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "¡SLOWPOKE sabe\nmuchísimo sobre\11POKéMON!\12¡Hasta tiene\nfósiles de POKéMON\11raros y extintos!{DONE}",
  ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "SLOWPOKE vino,\npero no le\11entendí.\12¡Creo que tiene\nun problema del\11habla!{DONE}",
  ["_FuchsiaPokecenterCooltrainerFText"] = "Hay un sendero\nestrecho al oeste\11de CIUDAD VERDE.\12Lleva a la SEDE\nde la LIGA POKéMON.\11La SEDE gobierna\11a todos los\11entrenadores.{DONE}",
  ["_FuchsiaPokecenterRockerText"] = "No puedes ganar\ncon un solo\11POKéMON fuerte.\12Es difícil, pero\ntienes que criarlos\11de forma\11equilibrada.{DONE}",
