  ["_GameOverText"] = "MEGAFONÍA: ¡Tu\nCACERÍA SAFARI ha\11terminado!{DONE}",
  ["_GameSavedText"] = "¡{PLAYER} guardó la\npartida!{DONE}",
  ["_GastlyDexEntry"] = "Casi invisible,\neste POKéMON\ngaseoso envuelve\12a su presa y la\nduerme sin que\nse dé cuenta",
  ["_GengarDexEntry"] = "Bajo la luna llena,\neste POKéMON imita\nlas sombras de la\12gente y se ríe del\nsusto que les da",
  ["_GeodudeDexEntry"] = "Vive en campos y\nmontañas. La gente\nlo confunde con\12rocas y a menudo\nlo pisa o tropieza\ncon él",
  ["_GetDexRatedText"] = "¿Quieres que valore\ntu POKéDEX?{DONE}",
  ["_GetOutText"] = "FANTASMA: Fuera...\nFuera...{PROMPT}",
  ["_GetmText"] = "¡A por él! {DONE}",
  ["_GettingPumpedText"] = "¡{USER}\nse está motivando!{PROMPT}",
  ["_GhostCantBeIDdText"] = "¡Vaya! ¡No se\npuede identificar\nal FANTASMA!{PROMPT}",
  ["_GloomDexEntry"] = "El fluido que le\nrezuma de la boca\nno es baba.\12Es un néctar que\nusa para atraer\na sus presas",
  ["_GoText"] = "¡Adelante! {DONE}",
  ["_GolbatDexEntry"] = "En cuanto muerde,\nno deja de drenar\nla energía de su\12víctima ni aunque\nse ponga demasiado\npesado para volar",
  ["_GoldeenDexEntry"] = "Su aleta caudal\nondea como un\nelegante vestido\12de baile, lo que le\nvale el apodo de\nReina del Agua",
  ["_GolduckDexEntry"] = "Se lo ve nadar con\nelegancia por las\norillas. A menudo\12se lo confunde con\nel monstruo japonés\nKappa",
  ["_GolemDexEntry"] = "Su cuerpo, como una\nroca, es durísimo.\nAguanta sin daño\12las explosiones de\ndinamita",
  ["_GoodText"] = "bien!{DONE}",
  ["_GotAwayText"] = "¡Escapaste sin\nproblemas!{PROMPT}",
