  ["_GravelerDexEntry"] = "Se desplaza rodando\ncuesta abajo. Pasa\npor encima de\12cualquier obstáculo\nsin frenar ni\ncambiar de rumbo",
  ["_GreatlyFellText"] = "{SCROLL}mucho{DONE}",
