  ["_GrewLevelText"] = "¡{RAM:wNameBuffer} subió\nal nivel {NUM:wCurEnemyLevel, 1, 3}!{DONE}",
  ["_GrimerDexEntry"] = "Aparece en lugares\nsucios. Prospera\nsorbiendo los\12lodos contaminados\nque bombean las\nfábricas",
  ["_GroundRoseText"] = "¡El suelo se\nlevantó en algún\nsitio!{DONE}",
  ["_GrowlitheDexEntry"] = "Muy protector de su\nterritorio.\nLadra y muerde para\12ahuyentar a los\nintrusos de su\nespacio",
  ["_GyaradosDexEntry"] = "Rara vez se lo ve\nen libertad. Enorme\ny feroz, es capaz\12de arrasar ciudades\nenteras en un\narrebato de furia",
  ["_GymStatueText1"] = "{RAM:wGymCityName}\nGIMNASIO POKéMON\11LÍDER: {RAM:wGymLeaderName}\12ENTRENADORES\nVENCEDORES:\n{RIVAL}{DONE}",
  ["_GymStatueText2"] = "{RAM:wGymCityName}\nGIMNASIO POKéMON\11LÍDER: {RAM:wGymLeaderName}\12ENTRENADORES\nVENCEDORES:\n{RIVAL}\11{PLAYER}{DONE}",
  ["_HMCantDeleteText"] = "¡Las técnicas MO\nno se pueden\nborrar!{PROMPT}",
  ["_HallOfFameOakText"] = "OAK: ¡Ejem!\n¡Enhorabuena,\11{PLAYER}!\12¡Esta planta es\nel SALÓN DE LA\11FAMA POKéMON!\12¡Aquí se honra a\nlos campeones de\11la LIGA POKéMON\11por sus hazañas!\12¡Sus POKéMON\ntambién quedan\11registrados en el\11SALÓN DE LA FAMA!\12¡{PLAYER}! ¡Te has\nesforzado mucho\11para ser el nuevo\11campeón de la LIGA!\12¡Enhorabuena,\n{PLAYER}, tú y tus\11POKéMON estáis en\11el SALÓN DE LA FAMA!{DONE}",
  ["_HasSubstituteText"] = "¡{USER}\ntiene un SUSTITUTO!{PROMPT}",
  ["_HaunterDexEntry"] = "Por su capacidad\nde atravesar\nparedes de bloques,\12se dice que viene\nde otra dimensión",
