  ["_HiddenItemBagFullText"] = "¡Pero {PLAYER} no\ntiene sitio para\11más objetos!{DONE}",
  ["_HisNameIsText"] = "¡Eso es! ¡Ahora me\nacuerdo! ¡Se\11llama {RIVAL}!{PROMPT}",
  ["_HitWithRecoilText"] = "¡{USER} recibió\ndaño de retroceso!{PROMPT}",
  ["_HitXTimesText"] = "¡Golpeó {NUM:wEnemyNumHits, 1, 1} veces!{PROMPT}",
  ["_HitmonchanDexEntry"] = "Aunque parezca no\nhacer nada, lanza\npuñetazos en\12ráfagas veloces\ncomo el rayo,\nimposibles de ver",
  ["_HitmonleeDexEntry"] = "Cuando tiene prisa,\nsus piernas se\nalargan poco a poco.\12Corre con soltura\ndando zancadas muy\nlargas",
  ["_HookedMonAttackedText"] = "¡El {RAM:wEnemyMonNick}\nque picó atacó!{PROMPT}",
  ["_HorseaDexEntry"] = "Se sabe que abate\ninsectos voladores\ncon precisos\12chorros de tinta\ndisparados desde la\nsuperficie del agua",
  ["_HurtByBurnText"] = "¡La quemadura\ndaña a {USER}!{PROMPT}",
  ["_HurtByLeechSeedText"] = "¡DRENADORAS\nabsorbe la energía\nde {USER}!{PROMPT}",
