  ["_HurtItselfText"] = "¡Se hirió a sí\nmismo por la\nconfusión!{PROMPT}",
  ["_HypnoDexEntry"] = "Cuando cruza la\nmirada con un\nenemigo, usa una\12mezcla de ataques\nPSI como HIPNOSIS\ny CONFUSIÓN",
  ["_IceHealText"] = "¡{RAM:wNameBuffer} se\ndescongeló!{DONE}",
  ["_IgnoredOrdersText"] = "¡{RAM:wBattleMonNick}\nignoró las órdenes!{PROMPT}",
  ["_IndigoPlateauHQText"] = "MESETA AÑIL\nSEDE DE LA LIGA POKéMON{DONE}",
  ["_IndigoPlateauLobbyCooltrainerFText"] = "¡A partir de aquí,\nte enfrentarás al\11ALTO MANDO uno a\11uno!\12¡Si ganas, una\npuerta se abre\11al siguiente\11entrenador!\11¡Buena suerte!{DONE}",
  ["_IndigoPlateauLobbyGymGuideText"] = "¡Eh! ¡Futuro\ncampeón!\12¡En la LIGA POKéMON\ntienes que\11enfrentarte al\11ALTO MANDO\11seguido.\12¡Si pierdes,\ntienes que\11empezar de nuevo!\11¡Es la hora! ¡A\11por ello!{DONE}",
  ["_IndigoPlateauStatuesText1"] = "MESETA AÑIL{PROMPT}",
  ["_IndigoPlateauStatuesText2"] = "¡La meta final de\nlos entrenadores!\11SEDE DE LA LIGA POKéMON{DONE}",
  ["_IndigoPlateauStatuesText3"] = "La máxima\nautoridad POKéMON\11SEDE DE LA LIGA POKéMON{DONE}",
  ["_IntoText"] = "\nen {RAM:wNameBuffer}!{DONE}",
  ["_IntroducePlayerText"] = "Primero, ¿cómo te\nllamas?{PROMPT}",
  ["_IntroduceRivalText"] = "Este es mi nieto.\nHa sido tu rival\11desde que erais\11bebés.\12...Eh, ¿cómo se\nllamaba?{PROMPT}",
