  ["_ItemUseBallText04"] = "¡Jo! ¡Y eso que\nestuvo muy cerca!{PROMPT}",
  ["_ItemUseBallText05"] = "¡Muy bien!\n¡Atrapaste a\11{RAM:wEnemyMonNick}!{DONE}",
