  ["_ItemUseText002"] = "{RAM:wStringBuffer}!{DONE}",
  ["_ItemWasStoredText"] = "¡{RAM:wNameBuffer} se\nguardó por PC.{PROMPT}",
  ["_ItemfinderFoundItemText"] = "¡Sí! El DETECTOR\nindica que hay un\11objeto cerca.{PROMPT}",
