  ["_ItemsCantBeUsedHereText"] = "Aquí no se pueden\nusar objetos.{PROMPT}",
  ["_ItsABiteText"] = "¡Oh!\n¡Ha picado!{PROMPT}",
  ["_IvysaurDexEntry"] = "Cuando el bulbo de\nsu lomo crece,\nparece perder la\12capacidad de\nsostenerse sobre\nlas patas traseras",
  ["_JigglypuffDexEntry"] = "Cuando sus enormes\nojos se iluminan,\ncanta una melodía\12misteriosamente\nrelajante que duerme\na sus enemigos",
  ["_JolteonDexEntry"] = "Acumula iones\nnegativos de la\natmósfera para\12descargar rayos de\n10000 voltios",
  ["_JustAMomentText"] = "Un momento.{DONE}",
  ["_JynxDexEntry"] = "Menea las caderas\nseductoramente al\nandar. Puede hacer\12que la gente baile\nal unísono con ella",
  ["_KabutoDexEntry"] = "POKéMON resucitado\na partir de un\nfósil hallado en lo\12que hace eones fue\nel fondo del océano",
  ["_KabutopsDexEntry"] = "Su forma esbelta es\nperfecta para nadar.\nCorta a la presa\12con las garras y le\ndrena los fluidos\ncorporales",
  ["_KabutopsFossilText"] = "Fósil de KABUTOPS\nUn POKéMON primi-\11tivo y raro.{DONE}",
  ["_KadabraDexEntry"] = "Emite de su cuerpo\nunas ondas alfa\nespeciales que\12causan dolor de\ncabeza con solo\nestar cerca",
  ["_KakunaDexEntry"] = "Casi incapaz de\nmoverse, este\nPOKéMON solo puede\12endurecer su\ncoraza para\nprotegerse",
  ["_KangaskhanDexEntry"] = "La cría rara vez\nsale de la bolsa\nprotectora de su\12madre hasta que\ncumple 3 años",
  ["_KeptGoingAndCrashedText"] = "¡{USER}\nsiguió y se\11estrelló!{PROMPT}",
  ["_KinglerDexEntry"] = "Su gran pinza tiene\nuna fuerza de\naplastamiento de\1210000 PS. Pero su\nenorme tamaño la\nhace difícil de usar",
  ["_KoffingDexEntry"] = "Como almacena en su\ncuerpo varios tipos\nde gases tóxicos,\12tiende a estallar\nsin previo aviso",
  ["_KrabbyDexEntry"] = "Sus pinzas no solo\nson armas podero-\nsas: también las\12usa para\nequilibrarse al\nandar de lado",
  ["_LancesRoomLanceAfterBattleText"] = "¡Aún no me creo\nque mis dragones\11perdieran contra\11ti, {PLAYER}!\12¡Ahora eres el\ncampeón de la\11LIGA POKéMON!\12...O lo serías,\npero te queda un\11reto más por\11delante.\12¡Tienes que\nenfrentarte a otro\11entrenador!\11Se llama...\12¡{RIVAL}!\n¡Venció al ALTO\11MANDO antes que tú!\12¡Es el verdadero\ncampeón de la\11LIGA POKéMON!{DONE}",
  ["_LancesRoomLanceBeforeBattleText"] = "¡Ah! ¡He oído\nhablar de ti,\11{PLAYER}!\12¡Lidero el ALTO\nMANDO! ¡Puedes\11llamarme LANCE,\11el entrenador de\11dragones!\12¡Ya sabes que los\ndragones son\11POKéMON míticos!\12¡Son difíciles de\natrapar y criar,\11pero su poder es\11superior!\12¡Son práctica-\nmente indestruc-\11tibles!\12Bueno, ¿listo\npara perder?\12¡Tu reto en la\nLIGA termina\11conmigo, {PLAYER}!{DONE}",
  ["_LancesRoomLanceEndBattleText"] = "¡Se acabó!\12Me cuesta\nadmitirlo, ¡pero\11eres un maestro\11POKéMON!{PROMPT}",
  ["_LaprasDexEntry"] = "POKéMON cazado en\nexceso hasta casi\nla extinción.\12Puede transportar\ngente de un lado a\notro del agua",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "¡El FANTASMA de la\nTORRE POKéMON ha\11desaparecido!\12¡Alguien debe de\nhaber calmado su\11alma inquieta!{DONE}",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "¡Odio a esos\nhorribles ROCKET!\12La pobre madre de\nese CUBONE...\12¡La mataron\ncuando intentaba\11escapar del TEAM\11ROCKET!{DONE}",
  ["_LavenderCuboneHouseCuboneText"] = "CUBONE: ¡Kyarugoo!{DONE}",
  ["_LavenderMartBaldingGuyText"] = "Busco objetos que\nsuben las capaci-\11dades de los\11POKéMON durante\11un solo combate.\12ATAQUE X, DEFENSA\nX, VELOCIDAD X y\11ESPECIAL X es lo\11que quiero.\12¿Sabes dónde los\npuedo conseguir?{DONE}",
  ["_LavenderMartCooltrainerMNuggetText"] = "Encontré una\nPEPITA en las\11montañas.\12¡Creí que no\nservía, pero la\11vendí por ₽5000!{DONE}",
  ["_LavenderMartCooltrainerMReviveText"] = "¿Conoces REVIVIR?\n¡Revive a\11cualquier POKéMON\11debilitado!{DONE}",
  ["_LavenderPokecenterGentlemanText"] = "¡El TEAM ROCKET\nhará lo que sea\11por el oro!{DONE}",
  ["_LavenderPokecenterGuyText"] = "Los CUBONE llevan\ncráneos, ¿verdad?\12¡La gente pagaría\nmucho por uno!{DONE}",
  ["_LavenderPokecenterLittleGirlText"] = "¡Vi morir a la\nmadre de CUBONE\11intentando escapar\11del TEAM ROCKET!{DONE}",
  ["_LavenderTownCooltrainerMText"] = "Este pueblo es\nconocido como el\11cementerio de los\11POKéMON.\12Se celebran\nfunerales en la\11TORRE POKéMON.{DONE}",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "¿Crees en los\nFANTASMAS?{DONE}",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "Jajaja, supongo\nque no.\12Esa mano blanca\nde tu hombro no\11es de verdad.{DONE}",
  ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "¿En serio? Así\nque hay creyen-\ntes...{DONE}",
  ["_LavenderTownPokemonHouseSignText"] = "CASA POKéMON DE\nVOLUNTARIOS DE\nLAVANDA{DONE}",
  ["_LavenderTownPokemonTowerSignText"] = "Que las almas de\nlos POKéMON\11descansen en paz\11TORRE POKéMON{DONE}",
  ["_LavenderTownSignText"] = "PUEBLO LAVANDA\nEl noble pueblo\11púrpura{DONE}",
  ["_LavenderTownSilphScopeSignText"] = "¡Nueva SILPH SCOPE!\12¡Haz visible lo\ninvisible!\12SILPH CO.{DONE}",
  ["_LavenderTownSuperNerdText"] = "Aparecieron\nFANTASMAS en la\11TORRE POKéMON.\12Creo que son los\nespíritus de los\11POKéMON que\11mataron los\11ROCKET.{DONE}",
  ["_LearnedMove1Text"] = "¡{RAM:wLearnMoveMonName} aprendió\n{RAM:wStringBuffer}!{DONE}",
  ["_LickitungDexEntry"] = "Estira la lengua\ncomo un camaleón.\nAl lamer a un\12enemigo le deja\nuna sensación de\nhormigueo",
