  ["_LinkBattleLostText"] = "¡{PLAYER} perdió\ncontra {RAM:wTrainerName}!{PROMPT}",
  ["_LinkCableHelpText1"] = "CONSEJOS\12Uso del Cable\nLink{PROMPT}",
  ["_LinkCableHelpText2"] = "¿Qué apartado\nquieres leer?{DONE}",
  ["_LinkCableInfoText1"] = "Cuando hayas\nconectado tu GAME\11BOY con otra GAME\11BOY, habla con el\11empleado de la\11derecha en\11cualquier CENTRO\11POKéMON.{PROMPT}",
  ["_LinkCableInfoText2"] = "El COLISEO te deja\njugar contra un\11amigo.{PROMPT}",
  ["_LinkCableInfoText3"] = "El CENTRO DE\nINTERCAMBIO sirve\11para cambiar\11POKéMON.{PROMPT}",
  ["_LinkCanceledText"] = "Se canceló la\nconexión.{DONE}",
  ["_LoafingAroundText"] = "{RAM:wBattleMonNick} está\nholgazaneando.{PROMPT}",
  ["_LoreleisRoomLoreleiAfterBattleText"] = "¡Eres mejor de lo\nque creía!\11¡Adelante!\12¡Solo has probado\nun poco del poder\11de la LIGA POKéMON!{DONE}",
  ["_LoreleisRoomLoreleiBeforeBattleText"] = "¡Bienvenido a la\nLIGA POKéMON!\12¡Soy LORELEI del\nALTO MANDO!\12¡Nadie me supera\ncon los POKéMON\11de hielo!\12¡Los ataques\ncongelantes son\11poderosos!\12¡Tus POKéMON\nquedarán a mi\11merced cuando\11estén congelados!\12¡Jajaja!\n¿Estás listo?{DONE}",
  ["_LoreleisRoomLoreleiDontRunAwayText"] = "Una voz:\n¡No huyas!{DONE}",
  ["_LoreleisRoomLoreleiEndBattleText"] = "¡Cómo\nte atreves!{PROMPT}",
  ["_LoweredItsHeadText"] = "\nagachó la cabeza!{PROMPT}",
  ["_MachampDexEntry"] = "Con sus pesados\nmúsculos lanza\npuñetazos capaces\12de mandar a la\nvíctima más allá\ndel horizonte",
  ["_MachokeDexEntry"] = "Su musculoso cuerpo\nes tan poderoso que\ndebe llevar un\12cinturón regulador\npara controlar sus\nmovimientos",
  ["_MachopDexEntry"] = "Le encanta desarro-\nllar sus músculos.\nEntrena todas las\12artes marciales\npara hacerse aún\nmás fuerte",
  ["_MadeWhirlwindText"] = "\ncreó un torbellino!{PROMPT}",
  ["_MagazinesText"] = "¡Revistas POKéMON!\12¡Cuadernos POKéMON!\12¡Gráficos POKéMON!{DONE}",
  ["_MagikarpDexEntry"] = "En un pasado remoto\nera algo más fuerte\nque los descendien-\12tes terriblemente\ndébiles que existen\nhoy",
  ["_MagmarDexEntry"] = "Su cuerpo arde\nsiempre con un\nresplandor naranja\12que le permite\nesconderse a la\nperfección entre las\nllamas",
  ["_MagnemiteDexEntry"] = "Usa la antigravedad\npara flotar.\nAparece sin previo\12aviso y usa ONDA\nTRUENO y ataques\nsimilares",
  ["_MagnetonDexEntry"] = "Se forma al unirse\nvarios MAGNEMITE.\nAparecen a menudo\12cuando estallan las\nmanchas solares",
  ["_MankeyDexEntry"] = "Se enfada con suma\nfacilidad. Puede\nestar dócil en un\12instante y liándose\na golpes al\nsiguiente",
  ["_MarowakDexEntry"] = "El hueso que sujeta\nes su arma clave.\nLo lanza con\12destreza como un\nbumerán para\nnoquear objetivos",
  ["_MartSignText"] = "¡Todo lo que\nnecesitas en\11objetos!\11TIENDA POKéMON{DONE}",
  ["_MeowthDexEntry"] = "Adora los objetos\nredondos. Recorre\nlas calles cada\12noche buscando\nmonedas sueltas\ntiradas por ahí",
  ["_MetapodDexEntry"] = "Este POKéMON es\nvulnerable mientras\nsu coraza está\12blanda, dejando al\ndescubierto su\ncuerpo tierno",
  ["_MewDexEntry"] = "Tan raro que muchos\nexpertos aún lo\ntienen por un\12espejismo. Solo\nunas pocas personas\nlo han visto",
  ["_MewtwoBattleText"] = "¡Mew!{DONE}",
  ["_MewtwoDexEntry"] = "Lo creó un cientí-\nfico tras años de\naterradores\12experimentos de\nempalme de genes e\ningeniería de ADN",
  ["_MimicLearnedMoveText"] = "¡{USER}\naprendió\11{RAM:wNameBuffer}!{PROMPT}",
  ["_MirrorMoveFailedText"] = "¡ESPEJO falló!{PROMPT}",
