  ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "¡Da mucho calor!\n¡Los POKéMON son\11muy achuchables!{DONE}",
  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "Esta es de verdad\nla casa del SR.\11FUJI.\12¡Es muy amable!\12¡Cuida de POKéMON\nabandonados y\11huérfanos!{DONE}",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "SR. FUJI: ¿Te ha\nservido mi\11FLAUTA?{DONE}",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "SR. FUJI: {PLAYER}.\12Tu misión con la\nPOKéDEX puede\11fracasar sin\11cariño hacia tus\11POKéMON.\12Creo que esto\npuede ayudarte.{PROMPT}",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "\12Al oír la POKé\nFLAUTA, los POKéMON\11dormidos se\11despiertan de\11golpe.\12Funciona con\ntodos los POKéMON\11dormidos.{DONE}",
  ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "¡Tienes que hacer\nsitio para esto!{DONE}",
  ["_MrFujisHouseMrFujiPokedexText"] = "¡Sorteo del Gran\nPremio Mensual\11POKéMON!\12El formulario de\nsolicitud está...\12¡No está! ¡Lo han\nrecortado!{DONE}",
  ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "¡{PLAYER} recibió\nuna {RAM:wStringBuffer}!{DONE}",
