  ["_MrFujisHousePsyduckText"] = "PSYDUCK: ¡Gwappa!{DONE}",
  ["_MrFujisHouseSuperNerdMrFujiHadBeenPrayingText"] = "El SR. FUJI había\nestado rezando\11solo por la madre\11de CUBONE.{DONE}",
  ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "Qué raro, el SR.\nFUJI no está.\11¿A dónde ha ido?{DONE}",
  ["_MrMimeDexEntry"] = "Si lo interrumpen\nmientras hace mímica,\nreparte manotazos\12al ofensor con sus\nmanos anchas",
  ["_MrPsychicsHouseMrPsychicReceivedTM29Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!{DONE}",
  ["_MrPsychicsHouseMrPsychicTM29ExplanationText"] = "¡La MT29 es\nPSÍQUICO!\12Puede bajar el\nESPECIAL del\11objetivo.{DONE}",
  ["_MrPsychicsHouseMrPsychicTM29NoRoomText"] = "¿Dónde piensas\nmeter esto?{DONE}",
  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "...¡Espera! ¡No\ndigas nada!\12¡Querías esto!{PROMPT}",
  ["_MtMoon1FBewareZubatSign"] = "¡Cuidado! ¡ZUBAT\nes un chupasangres!{DONE}",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "¿Cómo se sale de\naquí?{DONE}",
  ["_MtMoon1FCooltrainerF1BattleText"] = "¡Vaya! ¡Esto es\nmucho más grande\11de lo que creía!{DONE}",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "¡Oh!\n¡He perdido!{PROMPT}",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "He oído que aquí\nhay unos fósiles\11muy raros.{DONE}",
  ["_MtMoon1FCooltrainerF2BattleText"] = "¿Qué? Estoy\nesperando a que\11mis amigos me\11encuentren aquí.{DONE}",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "¿He perdido?{PROMPT}",
  ["_MtMoon1FHikerAfterBattleText"] = "¡Los críos como\ntú no deberían\11estar aquí!{DONE}",
  ["_MtMoon1FHikerBattleText"] = "¡EH! ¡Me has\nasustado! Ah, si\11solo eres un crío.{DONE}",
  ["_MtMoon1FHikerEndBattleText"] = "¡Vaya!\n¡Otro susto!{PROMPT}",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "Tengo que\nencontrar POKéMON\11más fuertes.{DONE}",
  ["_MtMoon1FSuperNerdBattleText"] = "¡Eh! ¡No te me\nacerques a\11hurtadillas!{DONE}",
  ["_MtMoon1FSuperNerdEndBattleText"] = "¡Mis\nPOKéMON no valen!{PROMPT}",
  ["_MtMoon1FYoungster1AfterBattleText"] = "Bajé aquí para\npresumir delante\11de las chicas.{DONE}",
  ["_MtMoon1FYoungster1BattleText"] = "¿Tú también has\nvenido a\11explorar?{DONE}",
  ["_MtMoon1FYoungster1EndBattleText"] = "¡Perder\napesta!{PROMPT}",
  ["_MtMoon1FYoungster2AfterBattleText"] = "¡Los he visto!\n¡Seguro que son\11del TEAM ROCKET!{DONE}",
  ["_MtMoon1FYoungster2BattleText"] = "Hay hombres\nsospechosos en la\11cueva. ¿Y tú?{DONE}",
  ["_MtMoon1FYoungster2EndBattleText"] = "¡Me\npillaste!{PROMPT}",
  ["_MtMoon1FYoungster3AfterBattleText"] = "¡ZUBAT es duro!\n¡Pero puede ser\11útil si atrapas\11uno!{DONE}",
  ["_MtMoon1FYoungster3BattleText"] = "¡Cruza esta cueva\npara llegar a\11CIUDAD CELESTE!{DONE}",
  ["_MtMoon1FYoungster3EndBattleText"] = "He\nperdido.{PROMPT}",
  ["_MtMoonB2FDomeFossilYouWantText"] = "¿Quieres el FÓSIL\nDOMO?{DONE}",
  ["_MtMoonB2FHelixFossilYouWantText"] = "¿Quieres el FÓSIL\nHÉLIX?{DONE}",
  ["_MtMoonB2FReceivedFossilText"] = "¡{PLAYER} consiguió\nel {RAM:wStringBuffer}!{DONE}",
  ["_MtMoonB2FRocket1AfterBattleText"] = "¡Me has hecho\nenfadar! ¡El TEAM\11ROCKET te pondrá\11en la lista\11negra!{DONE}",
  ["_MtMoonB2FRocket1BattleText"] = "¡El TEAM ROCKET\nencontrará los\11fósiles, los\11revivirá y los\11venderá por\11dinero!{DONE}",
  ["_MtMoonB2FRocket1EndBattleText"] = "¡Argh!\n¡Ahora sí que\11estoy furioso!{PROMPT}",
  ["_MtMoonB2FRocket2AfterBattleText"] = "¡Maldita sea! ¡Mis\ncompañeros no van\11a tolerar esto!{DONE}",
  ["_MtMoonB2FRocket2BattleText"] = "¡Nosotros, el\nTEAM ROCKET,\11somos gánsteres\11POKéMON!{DONE}",
  ["_MtMoonB2FRocket2EndBattleText"] = "¡La he\nfastidiado!{PROMPT}",
  ["_MtMoonB2FRocket3AfterBattleText"] = "¡Si encuentras un\nfósil, dámelo y\11lárgate!{DONE}",
  ["_MtMoonB2FRocket3BattleText"] = "¡Estamos dando un\ngran golpe aquí!\11¡Piérdete, crío!{DONE}",
  ["_MtMoonB2FRocket3EndBattleText"] = "Así que\neres bueno.{PROMPT}",
  ["_MtMoonB2FRocket4AfterBattleText"] = "Los POKéMON\nvivían aquí mucho\11antes de que\11llegara la gente.{DONE}",
  ["_MtMoonB2FRocket4BattleText"] = "¡Los niños\ndeberían dejar en\11paz a los\11mayores!{DONE}",
  ["_MtMoonB2FRocket4EndBattleText"] = "¡Estoy\nfurioso!{PROMPT}",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "¡Vale!\n¡Lo compartiré!{PROMPT}",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "De acuerdo.\n¡Entonces este es\11mío!{DONE}",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Lejos de aquí, en\nla ISLA CANELA,\11hay un LABORATORIO\11POKéMON.\12Investigan la\nregeneración de\11fósiles.{DONE}",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "¡Eh, alto!\12¡Yo encontré\nestos fósiles!\11¡Son los dos\11míos!{DONE}",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Mira, no tienes\nsitio para esto.{DONE}",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "¡Cogeremos uno\ncada uno!\11¡Nada de ser\11codicioso!{DONE}",
  ["_MtMoonPokecenterBenchGuyText"] = "¡Si tienes\ndemasiados POKéMON,\11deberías guardarlos\11por PC!{DONE}",
  ["_MtMoonPokecenterGentlemanText"] = "El TEAM ROCKET\nataca a los\11ciudadanos de\11CELESTE...\12¡El TEAM ROCKET\nsiempre está en\11las noticias!{DONE}",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "HOMBRE: ¡Hola!\n¡Tengo una oferta\11solo para ti!\12¡Te dejo un\nMAGIKARP estupendo\11por solo ₽500!\11¿Qué me dices?{DONE}",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "¡Vas a necesitar\nmás dinero que\11ese!{DONE}",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "HOMBRE: ¡Bueno,\nyo no hago\11devoluciones!{DONE}",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "¿No? ¡Solo lo\nhago como favor\11hacia ti!{DONE}",
  ["_MtMoonPokecenterYoungsterText"] = "Llevo 6 POKé BALLs\nen el cinturón.\12Como mucho, puedes\nllevar 6 POKéMON.{DONE}",
  ["_MukDexEntry"] = "Cubierto de un\nlodo repugnante y\nvil. Es tan tóxico\12que hasta sus\nhuellas contienen\nveneno",
  ["_MultiHitText"] = "¡Golpeó al enemigo\n{NUM:wPlayerNumHits, 1, 1} veces!{PROMPT}",
  ["_Museum1FGamblerText"] = "¡Ese sí que es un\nfósil magnífico!{DONE}",
  ["_Museum1FOldAmberText"] = "¡El ÁMBAR es\ntransparente y\11dorado!{DONE}",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "El ÁMBAR es resina\nde árbol fosili-\11zada.{DONE}",
  ["_Museum1FScientist1ComeAgainText"] = "¡Vuelve cuando\nquieras!{DONE}",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "¡No puedes colarte\npor la puerta de\11atrás!\12¡Ah, da igual!\n¿Sabes qué es el\11ÁMBAR?{DONE}",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "No tienes bastante\ndinero.{PROMPT}",
  ["_Museum1FScientist1GoToOtherSideText"] = "¡Ve al otro lado,\npor favor!{DONE}",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "¡Tómate tu tiempo\npara mirar!{DONE}",
  ["_Museum1FScientist1ThankYouText"] = "¡Bien, ₽50!\n¡Gracias!{DONE}",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "Hay un laboratorio\npor ahí que\11intenta resucitar\11POKéMON antiguos\11a partir de ÁMBAR.{DONE}",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "La entrada de\nniño cuesta ₽50.\12¿Quieres pasar?{DONE}",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "¡Chss! ¡Que\nexaminen el ÁMBAR\11VIEJO!{DONE}",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "¡{PLAYER} recibió\nÁMBAR VIEJO!{DONE}",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "¡Chss! ¡Creo que\neste trozo de\11ÁMBAR contiene\11ADN de POKéMON!\12¡Sería genial\nque se pudiera\11resucitar un\11POKéMON a partir\11de él!\12¡Pero mis colegas\nsimplemente me\11ignoran!\12¡Así que te pido\nun favor!\12¡Lleva esto a un\nLABORATORIO POKéMON\11y que lo examinen!{PROMPT}",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "¡No tienes sitio\npara esto!{DONE}",
  ["_Museum1FScientist3Text"] = "¡Estamos orgullo-\nsos de 2 fósiles\11de POKéMON prehis-\11tóricos muy raros!{DONE}",
  ["_Museum2FBrunetteGirlText"] = "¡Quiero un\nPIKACHU! ¡Es\11monísimo!\12¡Le pedí a mi\npapá que me\11atrapara uno!{DONE}",
  ["_Museum2FGrampsText"] = "¡20 de julio de\n1969!\12¡El primer\nalunizaje!\12¡Me compré una\ntele en color\11para verlo!{DONE}",
  ["_Museum2FHikerText"] = "¡Sí, un PIKACHU\npronto, te lo\11prometo!{DONE}",
  ["_Museum2FMoonStoneSignText"] = "Meteorito que\ncayó en el MONTE\11MOON.\11(¿PIEDRA LUNAR?){DONE}",
  ["_Museum2FScientistText"] = "Ahora tenemos una\nexposición sobre\11el espacio.{DONE}",
  ["_Museum2FSpaceShuttleSignText"] = "TRANSBORDADOR\nESPACIAL COLUMBIA{DONE}",
  ["_Museum2FYoungsterText"] = "¿PIEDRA LUNAR?\12¿Qué tiene de\nespecial?{DONE}",
  ["_MustRechargeText"] = "¡{USER}\ndebe recargarse!{PROMPT}",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "¿{RAM:wNameBuffer}, eh?\n¡Ese sí que es un\11nombre impecable!\12¡Cuida bien de\n{RAM:wNameBuffer}!{DONE}",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "¡Bien! ¡Ven cuando\nquieras!{DONE}",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "¿{RAM:wNameBuffer}, eh?\n¡Es un mote\11decente!\12Pero, ¿quieres\nque le ponga un\11nombre más bonito?\12¿Qué me dices?{DONE}",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "¡Bien! ¡Este\nPOKéMON pasa a\11llamarse {RAM:wBuffer}!\12¡Es mejor nombre\nque el de antes!{DONE}",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "¡Hola, hola!\n¡Soy el JUEZ DE\11NOMBRES oficial!\12¿Quieres que\nvalore los motes\11de tus POKéMON?{DONE}",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "¡Bien! ¿Cómo lo\nllamamos?{PROMPT}",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "¿Qué POKéMON\nquieres que mire?{PROMPT}",
  ["_NeedYourPokemonText"] = "Vale. Necesitaremos\ntus POKéMON.{DONE}",
  ["_NewBadgeRequiredText"] = "¡No! Hace falta\nuna MEDALLA nueva.{PROMPT}",
  ["_NewBicycleText"] = "¡Una BICI nueva y\nreluciente!{DONE}",
  ["_NidokingDexEntry"] = "En combate usa su\npoderosa cola para\naplastar, apretar\12y luego quebrar\nlos huesos de la\npresa",
  ["_NidoqueenDexEntry"] = "Sus duras escamas\nle dan una fuerte\nprotección. Usa su\12imponente corpu-\nlencia para\nejecutar ataques",
  ["_NidoranFDexEntry"] = "Aunque pequeño, sus\npúas venenosas\nhacen peligroso a\12este POKéMON.\nLa hembra tiene\ncuernos más cortos",
  ["_NidoranMDexEntry"] = "Tensa las orejas\npara detectar el\npeligro. Cuanto\12mayores sus cuernos,\nmás potente el\nveneno que segrega",
  ["_NidorinaDexEntry"] = "El cuerno de la\nhembra se desarrolla\ndespacio. Prefiere\12los ataques físicos\ncomo arañar y\nmorder",
  ["_NidorinoDexEntry"] = "POKéMON agresivo y\nrápido en atacar.\nEl cuerno de su\12cabeza segrega un\nveneno poderoso",
  ["_NinetalesDexEntry"] = "Muy listo y muy\nvengativo. Agarrar\nuna de sus muchas\12colas puede acarrear\nuna maldición de\n1000 años",
  ["_NoCyclingAllowedHereText"] = "Aquí no se puede\nmontar en bici.{PROMPT}",
  ["_NoEffectText"] = "¡Sin efecto!{PROMPT}",
  ["_NoMonText"] = "¿Qué? ¡Aquí no hay\nPOKéMON!{PROMPT}",
  ["_NoMoreRoomForItemText"] = "¡No hay sitio para\nmás objetos!{DONE}",
  ["_NoMovesLeftText"] = "¡A {RAM:wBattleMonNick} no le\nquedan ataques!{DONE}",
  ["_NoNibbleText"] = "¡Ni un mordisco!{PROMPT}",
  ["_NoRoomToStoreText"] = "No queda sitio\npara guardar\nobjetos.{PROMPT}",
  ["_NoRunningText"] = "¡No! ¡No se puede\nhuir de un combate\11de entrenador!{PROMPT}",
  ["_NoSurfingHereText"] = "¡Aquí no se puede\nusar SURF con\n{RAM:wNameBuffer}!{PROMPT}",
  ["_NoTrade1Text"] = "¡Ohh!\nEn fin...{DONE}",
  ["_NoTrade2Text"] = "Bueno, si no\nquieres...{DONE}",
  ["_NoTrade3Text"] = "Qué lástima.{DONE}",
  ["_NoWillText"] = "¡No hay voluntad\nde luchar!{PROMPT}",
  ["_NotEnoughCoinsSlotMachineText"] = "¡No tienes\nbastantes monedas!{PROMPT}",
  ["_NotHealthyEnoughText"] = "No está bastante\nsano.{PROMPT}",
  ["_NotThisTimeText"] = "¡Esta vez no!{PROMPT}",
  ["_NotVeryEffectiveText"] = "No es muy eficaz...{PROMPT}",
  ["_NothingHappenedText"] = "¡No pasó nada!{PROMPT}",
  ["_NothingHereText"] = "Parece que aquí\nno hay nada.{PROMPT}",
  ["_NothingStoredText"] = "No hay nada\nguardado.{PROMPT}",
  ["_NothingToCutText"] = "¡Aquí no hay nada\nque CORTAR!{PROMPT}",
  ["_NothingToDepositText"] = "No tienes nada\nque depositar.{PROMPT}",
  ["_OHKOText"] = "¡KO en un golpe!{PROMPT}",
  ["_OKExclamationText"] = "¡Vale!{DONE}",
  ["_OakLabEmailText"] = "¡Hay un correo\nelectrónico!\12...\12¡Atención a todos\nlos entrenadores\11POKéMON!\12¡Los entrenadores\nde élite de la\11LIGA POKéMON están\11listos para\11enfrentarse a\11todos!\12¡Trae a tus\nmejores POKéMON y\11comprueba tu\11nivel como\11entrenador!\12SEDE DE LA LIGA\nPOKéMON, MESETA\11AÑIL\12PD: PROF. OAK,\n¡venga a vernos!\11...{DONE}",
  ["_OakSpeechText1"] = "¡Hola!\n¡Bienvenido al\11mundo de los\11POKéMON!\12¡Me llamo OAK!\n¡La gente me\11llama el PROF.\11POKéMON!{PROMPT}",
  ["_OakSpeechText2A"] = "¡Este mundo está\nhabitado por\11criaturas llamadas\11POKéMON!{DONE}",
  ["_OakSpeechText2B"] = "\12Para algunas\npersonas, los\11POKéMON son\11mascotas. Otras\11los usan para\11combatir.\12Yo...\12Yo estudio los\nPOKéMON como\11profesión.{PROMPT}",
  ["_OakSpeechText3"] = "¡{PLAYER}!\12¡Tu propia leyenda\nPOKéMON está a\11punto de comenzar!\12¡Un mundo de\nsueños y aventuras\11con POKéMON te\11espera! ¡Vamos!{DONE}",
  ["_OaksAideComeBackText"] = "Ah. Ya veo.\12Cuando tengas {NUM:hOaksAideRequirement, 1, 3}\nclases, vuelve a\11por el {RAM:wOaksAideRewardItemName}.{DONE}",
  ["_OaksAideGotItemText"] = "¡{PLAYER} consiguió\nel {RAM:wOaksAideRewardItemName}!{DONE}",
  ["_OaksAideHereYouGoText"] = "¡Genial! ¡Has\natrapado {NUM:hOaksAideNumMonsOwned, 1, 3} clases \11de POKéMON!\11¡Enhorabuena!\12¡Aquí tienes!{PROMPT}",
  ["_OaksAideHiText"] = "¡Hola! ¿Me\nrecuerdas? ¡Soy el\11AYUDANTE del PROF.\11OAK!\12¡Si has atrapado {NUM:hOaksAideRequirement, 1, 3}\nclases de POKéMON,\11se supone que\11tengo que darte\11un {RAM:wOaksAideRewardItemName}!\12Y bien, {PLAYER}!\n¿Has atrapado al\11menos {NUM:hOaksAideRequirement, 1, 3} clases de\11POKéMON?{DONE}",
  ["_OaksAideNoRoomText"] = "¡Oh! Veo que no\ntienes sitio para\11el {RAM:wOaksAideRewardItemName}.{DONE}",
  ["_OaksAideUhOhText"] = "Veamos...\n¡Vaya! ¡Solo has\11atrapado {NUM:hOaksAideNumMonsOwned, 1, 3}\11clases de POKéMON!\12Necesitas {NUM:hOaksAideRequirement, 1, 3} clases\nsi quieres el\11{RAM:wOaksAideRewardItemName}.{DONE}",
  ["_OaksLabGirlText"] = "¡El PROF. OAK es\nla autoridad en\11POKéMON!\12¡Muchos entrena-\ndores POKéMON lo\11tienen en gran\11estima!{DONE}",
  ["_OaksLabGivePokeballsExplanationText"] = "\12Cuando aparece un\nPOKéMON salvaje,\11es presa libre.\12¡Solo tienes que\nlanzarle una POKé\nBALL e intentar\11atraparlo!\12Aunque esto no\nsiempre funciona.\12¡Un POKéMON sano\npodría escapar!\11¡Hay que tener\11suerte!{DONE}",
  ["_OaksLabLastMonText"] = "¡Ese es el último\nPOKéMON del PROF.\11OAK!{DONE}",
  ["_OaksLabMonEnergeticText"] = "¡Este POKéMON es\nmuy enérgico!{PROMPT}",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Ven a verme\nde vez en cuando.\12Quiero saber\ncómo va tu\11POKéDEX.{DONE}",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: ¡Ah, {PLAYER}!\12¿Cómo está mi\nviejo POKéMON?\12Vaya, parece que\nte tiene mucho\11cariño.\12¡Debes de tener\ntalento como\11entrenador POKéMON!\12¿Qué? ¿Tienes algo\npara mí?\12{PLAYER} entregó\nel PAQUETE de OAK.{DONE}",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK: ¡Me alegro de \nverte! ¿Cómo va tu \11POKéDEX? \11¡Aquí, déjame\11echar un vistazo!{PROMPT}",
  ["_OaksLabOak1ParcelThanksText"] = "\12¡Ah! ¡Es la POKé\nBALL personalizada\11que encargué!\11¡Gracias!{DONE}",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "¡POKéMON de todo\nel mundo te\11esperan, {PLAYER}!{DONE}",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "OAK: ¡{PLAYER},\ncría a tu joven\11POKéMON haciéndolo\11combatir!{DONE}",
  ["_OaksLabOak1ReceivedPokeballsText"] = "OAK: No puedes\nconseguir datos\11detallados de los\11POKéMON solo con\11verlos.\12¡Hay que atraparlos!\nUsa esto para\11capturar POKéMON\11salvajes.\12¡{PLAYER} consiguió\n5 POKé BALLs!{DONE}",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "OAK: Y bien,\n{PLAYER}, ¿qué\11POKéMON quieres?{DONE}",
  ["_OaksLabOak1YourPokemonCanFightText"] = "OAK: ¡Si aparece\nun POKéMON\11salvaje, tu\11POKéMON puede\11luchar contra él!{DONE}",
  ["_OaksLabOak2Text"] = "?{DONE}",
  ["_OaksLabOakBePatientText"] = "OAK: ¡Paciencia!\n¡{RIVAL}, tú\11también puedes\11tener uno!{DONE}",
  ["_OaksLabOakChooseMonText"] = "OAK: ¿{RIVAL}?\nDéjame pensar...\12¡Ah, es verdad,\nte dije que\11vinieras! ¡Espera!\12¡Aquí, {PLAYER}!\12¡Hay 3 POKéMON\naquí!\12¡Jaja!\12Están dentro de\nlas POKé BALLs.\12¡Cuando era joven,\nfui un entrenador\11POKéMON serio!\12¡En mi vejez solo\nme quedan 3, pero\11puedes quedarte\11uno! ¡Elige!{DONE}",
  ["_OaksLabOakDontGoAwayYetText"] = "OAK: ¡Eh! ¡No te\nvayas todavía!{DONE}",
  ["_OaksLabOakGotPokedexText"] = "OAK: ¡{PLAYER} y\n{RIVAL}! ¡Llevaos\11esto!\12¡{PLAYER} consiguió\nla POKéDEX de OAK!{DONE}",
  ["_OaksLabOakIHaveARequestText"] = "OAK: ¡Ah, sí!\nTengo una petición\11para vosotros dos.{DONE}",
  ["_OaksLabOakMyInventionPokedexText"] = "¡En el escritorio\nestá mi invento,\11la POKéDEX!\12¡Registra automá-\nticamente datos de\11los POKéMON que\11has visto o\11atrapado!\12¡Es una enciclo-\npedia de alta\11tecnología!{DONE}",
  ["_OaksLabOakThatWasMyDreamText"] = "Hacer una guía\ncompleta de todos\11los POKéMON del\11mundo...\12¡Ese era mi sueño!\12¡Pero soy demasiado\nviejo! ¡No puedo\11hacerlo!\12¡Así que quiero\nque vosotros dos\11cumpláis mi sueño\11por mí!\12¡En marcha, los\ndos!\12¡Es una gran\nempresa en la\11historia de los\11POKéMON!{DONE}",
  ["_OaksLabPokedexText"] = "¡Es como una\nenciclopedia, pero\11las páginas están\11en blanco!{DONE}",
  ["_OaksLabReceivedMonText"] = "¡{PLAYER} recibió\nun {RAM:wNameBuffer}!{DONE}",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: ¡Sí!\n¿Soy genial o\11qué?{PROMPT}",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: ¡Abuelo!\n¡Estoy harto de\11esperar!{DONE}",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Je, ¡yo\nno necesito ser\11codicioso como tú!\12¡Adelante, elige,\n{PLAYER}!{DONE}",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: ¡Eh,\n{PLAYER}! ¡El\11abuelo no está!{DONE}",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: ¡Abuelo!{DONE}",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "¿¡QUÉ!?\n¡Increíble!\11¡Elegí el POKéMON\11equivocado!{PROMPT}",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: ¡Entonces\nme quedo este!{DONE}",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: ¡Espera,\n{PLAYER}!\11¡Vamos a probar\11nuestros POKéMON!\12¡Venga, te reto!{DONE}",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: ¡Muy bien,\nabuelo! ¡Déjamelo\11todo a mí!\12{PLAYER}, me\nfastidia decirlo,\11¡pero no te\11necesito!\12¡Ya sé! ¡Le\npediré un MAPA\11PUEBLO a mi\11hermana!\12¡Le diré que no te\npreste uno,\11{PLAYER}! ¡Jajaja!{DONE}",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Mi\nPOKéMON parece\11mucho más fuerte.{DONE}",
  ["_OaksLabRivalReceivedMonText"] = "¡{RIVAL} recibió\nun {RAM:wNameBuffer}!{DONE}",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: ¡Vale!\n¡Haré combatir a\11mi POKéMON para\11curtirlo!\12¡{PLAYER}! ¡Abuelo!\n¡Nos vemos!{DONE}",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: ¡Eh!\n¡Abuelo! ¿Y yo\11qué?{DONE}",
