  ["_PPRestoredText"] = "Se restauraron\nlos PP.{PROMPT}",
  ["_PalletTownFisherText"] = "¡La tecnología es\nincreíble!\12¡Ahora puedes\nguardar y recuperar\11objetos y POKéMON\11como datos por PC!{DONE}",
  ["_PalletTownGirlText"] = "¡Yo también crío\nPOKéMON!\12¡Cuando se hacen\nfuertes, pueden\11protegerme!{DONE}",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "OAK: ¡Eh! ¡Espera!\n¡No salgas!{DONE}",
  ["_PalletTownOakItsUnsafeText"] = "OAK: ¡Es peligroso!\n¡Los POKéMON\11salvajes viven en\11la hierba alta!\12Necesitas tu\npropio POKéMON\11para protegerte.\11¡Ya sé!\12¡Toma, ven\nconmigo!{DONE}",
  ["_PalletTownOaksLabSignText"] = "LABORATORIO DE\nINVESTIGACIÓN\nPOKéMON DE OAK{DONE}",
