  ["_ParalyzedMayNotAttackText"] = "¡{TARGET} está\nparalizado! ¡Puede\11que no ataque!{PROMPT}",
  ["_ParasDexEntry"] = "Excava para chupar\nraíces de árbol.\nLas setas de su\12lomo crecen\nnutriéndose del\ninsecto anfitrión",
  ["_ParasectDexEntry"] = "Pareja anfitrión-\nparásito en la que\nla seta parásita ha\12dominado al insecto.\nPrefiere los lugares\nhúmedos",
