  ["_PartyMenuSwapMonText"] = "¿A dónde muevo al\nPOKéMON?{DONE}",
  ["_PartyMenuUseTMText"] = "¿En qué POKéMON\nusas la MT?{DONE}",
  ["_PersianDexEntry"] = "Aunque su pelaje\ntiene muchos\nadmiradores, es\12difícil de criar\ncomo mascota por su\ncarácter voluble",
  ["_PewterCityCooltrainerFText"] = "¡Se rumorea que\nlos CLEFAIRY\11vinieron de la\11luna!\12Aparecieron\ndespués de que la\11PIEDRA LUNAR\11cayera en el\11MONTE MOON.{DONE}",
  ["_PewterCityCooltrainerMText"] = "¡Aquí no hay\nmuchos entrenadores\11POKéMON serios!\12¡Son todos como\nCAZABICHOS, pero\11BROCK, del\11GIMNASIO PLATEADA,\11se lo toma muy en\11serio!{DONE}",
  ["_PewterCityGymSignText"] = "GIMNASIO POKéMON\nDE CIUDAD PLATEADA\11LÍDER: BROCK\12¡El entrenador\nPOKéMON duro como\nuna roca!{DONE}",
  ["_PewterCityMuseumSignText"] = "MUSEO DE CIENCIAS\nDE PLATEADA{DONE}",
  ["_PewterCityPokecenterGuyText"] = "¡Bostezo!\12Cuando JIGGLYPUFF\ncanta, a los\11POKéMON les entra\11sueño...\12...A mí también...\nZzz...{DONE}",
  ["_PewterCityPoliceNoticeSignText"] = "¡AVISO!\12¡Unos ladrones\nhan estado\11robando fósiles\11de POKéMON en el\11MONTE MOON!\11¡Llama a la\11POLICÍA DE\11PLATEADA con\11cualquier pista!{DONE}",
  ["_PewterCitySignText"] = "CIUDAD PLATEADA\nUna ciudad gris\11como la piedra{DONE}",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "¿Has visto el\nMUSEO?{DONE}",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "¡Está aquí mismo!\nHay que pagar\11para entrar, ¡pero\11merece la pena!\11¡Nos vemos!{DONE}",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "¿A que eran\nasombrosos esos\11fósiles del MONTE\11MOON?{DONE}",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "¿En serio?\n¡Tienes que ir\11sí o sí!{DONE}",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "¡Chsss!\n¿Sabes qué estoy\11haciendo?{DONE}",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "¡Estoy rociando\nREPEL para\11mantener a los\11POKéMON fuera de\11mi jardín!{DONE}",
  ["_PewterCitySuperNerd2ThatsRightText"] = "¡Eso es!\n¡Es un trabajo\11duro!{DONE}",
  ["_PewterCityTrainerTipsText"] = "CONSEJOS\12¡Cualquier POKéMON\nque participe en\11un combate, por\11breve que sea,\11gana EXP!{DONE}",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "¡Si tienes lo que\nhay que tener, ve\11a por BROCK!{DONE}",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Eres entrenador,\n¿verdad? ¡BROCK\11busca nuevos\11retadores!\11¡Sígueme!{DONE}",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\12¡Esa es una\nMEDALLA oficial de\11la LIGA POKéMON!\12¡Los POKéMON de\nquien la lleva se\11vuelven más\11poderosos!\12¡Ahora se puede\nusar DESTELLO en\11cualquier momento!{PROMPT}",
  ["_PewterGymBrockPostBattleAdviceText"] = "¡Hay todo tipo de\nentrenadores en\11el mundo!\12¡Pareces muy\ndotado como\11entrenador POKéMON!\12¡Ve al GIMNASIO de\nCELESTE y pon a\11prueba tus\11capacidades!{DONE}",
  ["_PewterGymBrockPreBattleText"] = "¡Soy BROCK!\n¡Soy el LÍDER del\11GIMNASIO PLATEADA!\12¡Creo en una\ndefensa dura como\11la roca y en la\11determinación!\12¡Por eso todos\nmis POKéMON son\11de tipo roca!\12¿Aún quieres\nretarme? ¡Pues\11muy bien!\11¡Enséñame lo\11mejor que tengas!{DONE}",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Te\nsubestimé.\12Como prueba de tu\nvictoria, ¡aquí\11tienes la MEDALLA\11ROCA!\12¡{PLAYER} recibió\nla MEDALLA ROCA!{DONE}",
  ["_PewterGymBrockWaitTakeThisText"] = "¡Espera! ¡Llévate\nesto!{DONE}",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Eres bastante\nbueno, ¡pero no\11tanto como BROCK!{DONE}",
  ["_PewterGymCooltrainerMBattleText"] = "¡Alto ahí, crío!\12¡Todavía estás a\naños luz de\11enfrentarte a\11BROCK!{DONE}",
  ["_PewterGymCooltrainerMEndBattleText"] = "¡Vaya!\12¡Los años luz no\nson tiempo! ¡Miden\11distancia!{PROMPT}",
  ["_PewterGymGuideAdviceText"] = "¡El primer POKéMON\nque sale en un\11combate es el que\11está arriba de la\11LISTA POKéMON!\12¡Cambiando el\norden de los\11POKéMON, los\11combates pueden\11ser más fáciles!{DONE}",
  ["_PewterGymGuideBeginAdviceText"] = "¡Muy bien! ¡Vamos\nallá!{PROMPT}",
  ["_PewterGymGuideFreeServiceText"] = "¡Es un servicio\ngratis! ¡Vamos\11allá!{PROMPT}",
  ["_PewterGymGuidePostBattleText"] = "¡Justo lo que\npensaba! ¡Tienes\11madera de campeón\11POKéMON!{DONE}",
  ["_PewterGymGuidePreAdviceText"] = "¡Hola! ¡Se nota\nque tienes lo que\11hace falta para\11ser campeón\11POKéMON!\12No soy entrenador,\npero puedo decirte\11cómo ganar.\12¡Deja que te lleve\nhasta la cima!{DONE}",
  ["_PewterGymReceivedTM34Text"] = "¡{PLAYER} recibió\nla MT34!{DONE}",
  ["_PewterGymTM34NoRoomText"] = "¡No tienes sitio\npara esto!{DONE}",
  ["_PewterMartSuperNerdText"] = "¡Pueden pasar\ncosas buenas si\11crías a los\11POKéMON con\11esmero, hasta a\11los débiles!{DONE}",
  ["_PewterMartYoungsterText"] = "¡Un viejo turbio\nme hizo comprar\11este POKéMON pez\11tan raro!\12¡Es totalmente\ndébil y me costó\11₽500!{DONE}",
  ["_PewterNidoranHouseLittleBoyText"] = "¡NIDORAN, sentado!{DONE}",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Nuestro POKéMON es\nde fuera, así que\11cuesta manejarlo.\12Uno de fuera es un\nPOKéMON que\11consigues en un\11intercambio.\12¡Crece rápido,\npero puede que\11ignore a un\11entrenador\11inexperto en\11combate!\12Si tuviéramos\nalguna MEDALLA...{DONE}",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: ¡Bwbw!{DONE}",
  ["_PewterPokecenterGentlemanText"] = "¿¡Qué!?\12¿El TEAM ROCKET\nen el MONTE MOON?\11¿Eh? ¡Estoy al\11teléfono!\12¡Largo!{DONE}",
  ["_PewterPokecenterJigglypuffText"] = "JIGGLYPUFF: ¡Puu\npupuu!{DONE}",
  ["_PewterSpeechHouseGamblerText"] = "¡Los POKéMON\naprenden nuevas\11técnicas a medida\11que crecen!\12¡Pero algunos\nataques debe\11enseñarlos el\11entrenador!{DONE}",
  ["_PewterSpeechHouseYoungsterText"] = "¡Los POKéMON son\nmás fáciles de\11atrapar cuando\11están heridos o\11dormidos!\12¡Pero no es\nseguro!{DONE}",
  ["_PickUpPayDayMoneyText"] = "¡{PLAYER} recogió\n₽{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}!{PROMPT}",
  ["_PidgeotDexEntry"] = "Al cazar, roza la\nsuperficie del agua\na gran velocidad\12para abatir presas\nincautas como\nMAGIKARP",
  ["_PidgeottoDexEntry"] = "Muy protector de su\ndilatado territorio,\neste POKéMON\12picotea con fiereza\na cualquier intruso",
  ["_PidgeyDexEntry"] = "Muy común en\nbosques y arboledas.\nAgita las alas a\12ras del suelo para\nlevantar una arena\ncegadora",
  ["_PikachuDexEntry"] = "Cuando se juntan\nvarios de estos\nPOKéMON, su\12electricidad puede\nacumularse y causar\ntormentas de rayos",
  ["_PinsirDexEntry"] = "Si no logra aplas-\ntar a la víctima\ncon sus pinzas, la\12hace girar y la\nlanza con fuerza",
