  ["_PokemonCenterWelcomeText"] = "¡Bienvenido a\nnuestro CENTRO\11POKéMON!\12¡Curamos a tus\nPOKéMON hasta\11dejarlos en\11perfecto estado!{PROMPT}",
  ["_PokemonFaintedText"] = "¡{RAM:wNameBuffer}\nse debilitó!{DONE}",
  ["_PokemonFanClubBagFullText"] = "¡Haz sitio para\nesto!{DONE}",
  ["_PokemonFanClubChairFinalText"] = "¡Hola, {PLAYER}!\12¿Has venido a\nverme para hablar\11de mis POKéMON\11otra vez?\12¿No? ¡Qué lástima!{DONE}",
  ["_PokemonFanClubChairmanIntroText"] = "¡Presido el Club\nde Fans POKéMON!\12¡He reunido más\nde 100 POKéMON!\12¡Soy muy exigente\ncon los POKéMON!\12Así que...\12¿Has venido a\nescuchar hablar\11de mis POKéMON?{DONE}",
  ["_PokemonFanClubChairmanStoryText"] = "¡Bien!\n¡Entonces escucha!\12Mi querido\nRAPIDASH...\12Es...mono...\nprecioso...listo...\11además...asombroso...\11¿tú crees?...\11ah, sí...es...\11impresionante...\11amable...\11¡lo adoro!\12Lo abrazas...\ncuando...duerme...\11calentito y\11achuchable...\11espectacular...\11arrebatador...\11¡Uy! ¡Mira qué\11hora es! ¡Te he\11entretenido\11demasiado!\12¡Gracias por\nescucharme! ¡Quiero\11que tengas esto!{PROMPT}",
  ["_PokemonFanClubExplainBikeVoucherText"] = "\12¡Cámbialo por una\nBICI!\12¡Tranquilo, mi\nFEAROW me lleva\11VOLANDO a\11cualquier parte!\12¡Así que no\nnecesito BICI!\12¡Espero que te\nguste ir en bici!{DONE}",
  ["_PokemonFanClubNoStoryText"] = "Ah. ¡Vuelve cuando\nquieras oír mi\11historia!{DONE}",
  ["_PokemonFanClubPikachuFanBetterText"] = "¡Bah! ¡Mi PIKACHU\nes el doble de\11mono que ese!{DONE}",
  ["_PokemonFanClubPikachuFanNormalText"] = "¿No admiras la\nadorable colita\11de mi PIKACHU?{DONE}",
  ["_PokemonFanClubPikachuText"] = "PIKACHU: ¡Chu!\n¡Pikachu!{DONE}",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "¡{PLAYER} recibió\nun {RAM:wStringBuffer}!{DONE}",
  ["_PokemonFanClubReceptionistText"] = "Nuestro Presidente\nhabla mucho de\11POKéMON.{DONE}",
  ["_PokemonFanClubSeelFanBetterText"] = "¡Ay, madre!\12¡Mi SEEL es mucho\nmás atractivo!{DONE}",
  ["_PokemonFanClubSeelFanNormalText"] = "¡Me encanta mi\nSEEL!\12¡Chilla cuando lo\nabrazo!{DONE}",
  ["_PokemonFanClubSeelText"] = "SEEL: ¡Kyuoo!{DONE}",
  ["_PokemonFanClubSign1Text"] = "¡Escuchemos todos\ncon educación a\11los demás\11entrenadores!{DONE}",
  ["_PokemonFanClubSign2Text"] = "¡Si alguien\npresume, presume\11tú también!{DONE}",
  ["_PokemonFightingFitText"] = "¡Gracias!\n¡Tus POKéMON\11están en plena\11forma!{PROMPT}",
  ["_PokemonMansion1FScientistAfterBattleText"] = "¿Una llave? No sé\nde qué me hablas.{DONE}",
  ["_PokemonMansion1FScientistBattleText"] = "¿Quién eres? Aquí\nno debería haber\11nadie.{DONE}",
