  ["_PokemonMansion1FSwitchText"] = "¡Un interruptor\nsecreto!\12¿Lo pulsas?{DONE}",
  ["_PokemonMansion2FDiary1Text"] = "Diario: 5 de julio\nGuyana,\11Sudamérica\12Se descubrió un\nnuevo POKéMON en\11lo hondo de la\11jungla.{DONE}",
  ["_PokemonMansion2FDiary2Text"] = "Diario: 10 de julio\nBautizamos al\11POKéMON recién\11descubierto: MEW.{DONE}",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "¡Los interruptores\nabren y cierran\11grupos alternos\11de puertas!{DONE}",
  ["_PokemonMansion2FSuperNerdBattleText"] = "¡No puedo salir!\n¡Este sitio viejo\11es un gran\11rompecabezas!{DONE}",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "¡Oh, no!\n¡Mi bolsa de\11botín!{PROMPT}",
  ["_PokemonMansion2FSwitchNotPressedText"] = "¡Todavía no!{DONE}",
  ["_PokemonMansion2FSwitchPressedText"] = "¿Quién no lo\nharía?{PROMPT}",
  ["_PokemonMansion2FSwitchText"] = "¡Un interruptor\nsecreto!\12¿Lo pulsas?{DONE}",
  ["_PokemonMansion3FDiaryText"] = "Diario: 6 de feb.\nMEW dio a luz.\12Llamamos al recién\nnacido MEWTWO.{DONE}",
  ["_PokemonMansion3FScientistAfterBattleText"] = "¿Así que estás\natascado? ¡Prueba\11a saltar por\11allí!{DONE}",
  ["_PokemonMansion3FScientistBattleText"] = "Mi mentor vivió\naquí una vez.{DONE}",
  ["_PokemonMansion3FScientistEndBattleText"] = "¡Uf!\n¡Aplastante!{PROMPT}",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Me pregunto a\ndónde ha ido mi\11compañero.{DONE}",
  ["_PokemonMansion3FSuperNerdBattleText"] = "¡Este sitio es\ngigante!{DONE}",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "¡Ayay!{PROMPT}",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "Se pueden\nencontrar cosas\11tiradas por ahí.{DONE}",
  ["_PokemonMansionB1FBurglarBattleText"] = "Vaya. ¿Dónde\nestoy ahora?{DONE}",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "¡Auuu!{PROMPT}",
  ["_PokemonMansionB1FDiaryText"] = "Diario: 1 de sept.\nMEWTWO es demasiado\11poderoso.\12No hemos logrado\nfrenar sus\11tendencias\11violentas...{DONE}",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "¡Me gusta esto!\n¡Favorece mis\11estudios!{DONE}",
  ["_PokemonMansionB1FScientistBattleText"] = "Este sitio es\nideal para un\11laboratorio.{DONE}",
  ["_PokemonMansionB1FScientistEndBattleText"] = "¿A qué ha\nvenido eso?{PROMPT}",
  ["_PokemonSellingGreetingText"] = "¿Qué te gustaría\nvender?{DONE}",
  ["_PokemonStuffText"] = "¡Hala! ¡Un montón\nde cosas de\11POKéMON!{DONE}",
  ["_PokemonTower1FBaldingGuyText"] = "Vine a rezar por\nmi CLEFAIRY.\12¡Snif! No puedo\ndejar de llorar...{DONE}",
  ["_PokemonTower1FChannelerText"] = "¡Soy una MÉDIUM!\n¡Hay espíritus\11haciendo\11travesuras!{DONE}",
  ["_PokemonTower1FGirlText"] = "Mi GROWLITHE...\n¿Por qué moriste?{DONE}",
  ["_PokemonTower1FMiddleAgedWomanText"] = "¿Has venido a\npresentar tus\11respetos?\11¡Bendito seas!{DONE}",
  ["_PokemonTower1FReceptionistText"] = "La TORRE POKéMON\nse erigió en\11memoria de los\11POKéMON fallecidos.{DONE}",
  ["_PokemonTower2FChannelerText"] = "¡Ni siquiera\nnosotros pudimos\11identificar a los\11FANTASMAS\11errantes!\12Una SILPH SCOPE\npodría desenmasca-\11rarlos.{DONE}",
  ["_PokemonTower2FRivalDefeatedText"] = "¿Qué?\n¡Serás rata!\12¡Y encima me lo\ntomé con calma\11contigo!{PROMPT}",
  ["_PokemonTower2FRivalHowsYourDexText"] = "¿Cómo va tu\nPOKéDEX, colega?\11¡Yo acabo de\11atrapar un CUBONE!\12¡Todavía no\nencuentro el\11MAROWAK adulto!\12¡Dudo que quede\nalguno! ¡Bueno,\11mejor me voy!\11¡Tengo mucho que\11hacer, colega!\12¡Nos vemos!{DONE}",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}: ¡Vaya,\nmira todos tus\11POKéMON canijos!\12¡Cúrtelos un poco\nmás!{PROMPT}",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}: ¡Eh,\n{PLAYER}! ¿Qué te\11trae por aquí?\11¡Tus POKéMON no\11parecen muertos!\12¡Yo al menos puedo\nhacer que se\11debiliten! ¡Vamos,\11colega!{DONE}",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "Los FANTASMAS se\npueden identificar\11con la SILPH SCOPE.{DONE}",
  ["_PokemonTower3FChanneler1BattleText"] = "Uurg...Awaa...\nJuju...graa..{DONE}",
  ["_PokemonTower3FChanneler1EndBattleText"] = "¡Hwa!\n¡Estoy salvada!{PROMPT}",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "¡Lo siento!\n¡Estaba poseída!{DONE}",
  ["_PokemonTower3FChanneler2BattleText"] = "Kekeke....\n¡Kuaaah!{DONE}",
  ["_PokemonTower3FChanneler2EndBattleText"] = "¿Mmm?\n¿Qué estoy\11haciendo?{PROMPT}",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "¡Mis amigas\ntambién estaban\11poseídas!{DONE}",
  ["_PokemonTower3FChanneler3BattleText"] = "¡Fuera de aquí!\n¡Espíritu maligno!{DONE}",
  ["_PokemonTower3FChanneler3EndBattleText"] = "¡Uf!\n¡El espíritu se\11fue!{PROMPT}",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "Debía de estar\nsoñando...{DONE}",
  ["_PokemonTower4FChanneler1BattleText"] = "¡FANTASMA! ¡No!\n¡Kuaaah!{DONE}",
  ["_PokemonTower4FChanneler1EndBattleText"] = "¿Dónde\nestá el FANTASMA?{PROMPT}",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "No podemos\ndescubrir la\11identidad de los\11FANTASMAS.{DONE}",
  ["_PokemonTower4FChanneler2BattleText"] = "¡Que te maldigan\ncomo a mí!\11¡Kuaaah!{DONE}",
  ["_PokemonTower4FChanneler2EndBattleText"] = "¡Qué!{PROMPT}",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Que las almas de\nlos POKéMON\11difuntos descansen\11en paz...{DONE}",
  ["_PokemonTower4FChanneler3BattleText"] = "Jujuju...\n¡No me venzas!{DONE}",
  ["_PokemonTower4FChanneler3EndBattleText"] = "¿Eh?\n¿Quién? ¿Qué?{PROMPT}",
  ["_PokemonTower5FChanneler1Text"] = "¡Ven, criatura! ¡He\nsellado este lugar\11con magia blanca!\12¡Aquí puedes\ndescansar!{DONE}",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "¡Estaba poseída!{DONE}",
  ["_PokemonTower5FChanneler2BattleText"] = "Dame...tu...\nalma...{DONE}",
  ["_PokemonTower5FChanneler2EndBattleText"] = "¡Jadeo!{PROMPT}",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "¡Estaba poseída!{DONE}",
  ["_PokemonTower5FChanneler3BattleText"] = "Te...unirás...\na...nosotras...{DONE}",
  ["_PokemonTower5FChanneler3EndBattleText"] = "¡Qué\npesadilla!{PROMPT}",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "¡Recobré el\nsentido!{DONE}",
  ["_PokemonTower5FChanneler4BattleText"] = "¡Zombis!{DONE}",
  ["_PokemonTower5FChanneler4EndBattleText"] = "¿Ja?{PROMPT}",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "¡Caí ante los\nespíritus malignos\11pese a mi\11entrenamiento!{DONE}",
  ["_PokemonTower5FChanneler5BattleText"] = "Urga...\nUrf....{DONE}",
  ["_PokemonTower5FChanneler5EndBattleText"] = "¡Buu!{PROMPT}",
  ["_PokemonTower5FPurifiedZoneText"] = "¡Entraste en una\nzona purificada y\11protegida!\12¡Los POKéMON de\n{PLAYER} se curan\11del todo!{DONE}",
  ["_PokemonTower6FBeGoneText"] = "Fuera de aquí...\nIntrusos...{DONE}",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Me siento anémica\ny débil...{DONE}",
  ["_PokemonTower6FChanneler1BattleText"] = "Dame...\nsangre...{DONE}",
  ["_PokemonTower6FChanneler1EndBattleText"] = "¡Gemido!{PROMPT}",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "¡No se me cayó el\npelo! ¡Era un\11espíritu maligno!{DONE}",
  ["_PokemonTower6FChanneler2BattleText"] = "Urf... ¡Kuaah!{DONE}",
  ["_PokemonTower6FChanneler2EndBattleText"] = "¡Se me\ncayó algo!{PROMPT}",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "¿Qué está pasando\naquí?{DONE}",
  ["_PokemonTower6FChanneler3BattleText"] = "Ke..ke...ke...\n¡¡ke..ke...ke!!{DONE}",
  ["_PokemonTower6FChanneler3EndBattleText"] = "¡Kee!{PROMPT}",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "¡El FANTASMA era\nel alma inquieta\11de la madre de\11CUBONE!{DONE}",
  ["_PokemonTower6FSoulWasCalmedText"] = "El alma de la\nmadre se calmó.\12¡Partió al más\nallá!{DONE}",
  ["_PokemonTower7FMrFujiRescueText"] = "SR. FUJI: ¿Eh?\n¿Has venido a\11salvarme?\12Gracias. Pero yo\nvine aquí por\11voluntad propia.\12Vine a calmar el\nalma de la madre\11de CUBONE.\12Creo que el\nespíritu de\11MAROWAK ha\11partido al más\11allá.\12¡Debo agradecerte\ntu amable\11preocupación!\12Sígueme a mi casa,\nla CASA POKéMON al\11pie de esta torre.{DONE}",
  ["_PokemonTower7FRocket1AfterBattleText"] = "¡Esto no lo voy a\nolvidar!{DONE}",
  ["_PokemonTower7FRocket1BattleText"] = "¿Qué quieres?\n¿Por qué estás\11aquí?{DONE}",
  ["_PokemonTower7FRocket1EndBattleText"] = "¡Me rindo!{PROMPT}",
  ["_PokemonTower7FRocket2AfterBattleText"] = "¡Los POKéMON solo\nsirven para ganar\11dinero!\12¡No te metas en\nnuestros asuntos!{DONE}",
  ["_PokemonTower7FRocket2BattleText"] = "¡Este viejo vino\na quejarse de que\11dañamos POKéMON\11inútiles!\12¡Lo estamos\nhablando como\11adultos!{DONE}",
  ["_PokemonTower7FRocket2EndBattleText"] = "¡Por favor!\n¡Basta!{PROMPT}",
  ["_PokemonTower7FRocket3AfterBattleText"] = "¡No te vas a\nsalir con la\11tuya!{DONE}",
  ["_PokemonTower7FRocket3BattleText"] = "¡No vas a salvar\na nadie, crío!{DONE}",
  ["_PokemonTower7FRocket3EndBattleText"] = "¡No luches\ncontra el TEAM\11ROCKET!{PROMPT}",
  ["_PoliwagDexEntry"] = "Sus recién nacidas\npatas le impiden\ncorrer. Parece\12preferir nadar a\nintentar mantenerse\nde pie",
  ["_PoliwhirlDexEntry"] = "Puede vivir dentro\ny fuera del agua.\nFuera del agua suda\12para mantener el\ncuerpo viscoso",
  ["_PoliwrathDexEntry"] = "Nadador experto\ntanto a crol como\na braza. Adelanta\12con facilidad a los\nmejores nadadores\nhumanos",
  ["_PonytaDexEntry"] = "Sus cascos son 10\nveces más duros que\nlos diamantes.\12Puede dejar cual-\nquier cosa\ncompletamente plana",
  ["_PoofText"] = " ¡Puf!{DONE}",
  ["_PorygonDexEntry"] = "POKéMON hecho por\ncompleto de código\nde programación.\12Capaz de moverse\nlibremente por el\nciberespacio",
  ["_PotionText"] = "¡{RAM:wNameBuffer}\nrecuperó {NUM:wHPBarHPDifference, 2, 3} PS!{DONE}",
  ["_PowerPlantVoltorbBattleText"] = "¡Bzzzt!{DONE}",
  ["_PowerPlantZapdosBattleText"] = "¡Gyaoo!{DONE}",
  ["_PrimeapeDexEntry"] = "Siempre furioso y\nademás tenaz. No\nabandona la\12persecución de su\npresa hasta\natraparla",
  ["_PsyduckDexEntry"] = "Mientras adormece\na sus enemigos con\nsu mirada perdida,\12este astuto POKéMON\nusa poderes\npsicoquinéticos",
  ["_PushStartText"] = "¡Pulsa START para\nabrir el MENÚ!{DONE}",
  ["_RaichuDexEntry"] = "Su larga cola le\nsirve de toma de\ntierra para prote-\12gerse de su propia\nalta tensión",
  ["_RaisePPWhichTechniqueText"] = "¿De qué técnica\nsubes los PP?{DONE}",
  ["_RanAwayScaredText"] = "¡{TARGET}\nhuyó asustado!{PROMPT}",
  ["_RanFromBattleText"] = "¡{USER}\nhuyó del combate!{PROMPT}",
  ["_RapidashDexEntry"] = "Muy competitivo,\neste POKéMON\npersigue todo lo\12que se mueva rápido\ncon la esperanza de\necharle una carrera",
  ["_RareCandyText"] = "¡{RAM:wNameBuffer} subió\nal nivel {NUM:wCurEnemyLevel, 1, 3}!{DONE}",
  ["_RaticateDexEntry"] = "Usa los bigotes\npara mantener el\nequilibrio.\12Al parecer se vuelve\nlento si se los\ncortan",
  ["_RattataDexEntry"] = "Muerde cualquier\ncosa al atacar.\nPequeño y muy\12rápido, es una\nvisión común en\nmuchos lugares",
  ["_RedBedroomSNESText"] = "¡{PLAYER} está\njugando a la SNES!\11...¡Vale!\11¡Es hora de irse!{DONE}",
  ["_RedsHouse1FMomLookingGreatText"] = "MAMÁ: ¡Ah, qué\nbien! ¡Tú y tus\11POKéMON tenéis\11muy buena pinta!\11¡Cuídate!{DONE}",
  ["_RedsHouse1FMomWakeUpText"] = "MAMÁ: Claro.\nTodos los chicos\11se van de casa\11algún día.\11Lo dijeron en la\11tele.\12El PROF. OAK, el\nvecino, te está\11buscando.{DONE}",
  ["_RedsHouse1FMomYouShouldRestText"] = "MAMÁ: ¡{PLAYER}!\nDeberías descansar\11un momento.{PROMPT}",
  ["_RedsHouse1FTVStandByMeMovieText"] = "Ponen una peli en\nla tele. Cuatro\11chicos caminan\11por unas vías de\11tren.\12Yo también\ndebería irme.{DONE}",
  ["_RedsHouse1FTVWrongSideText"] = "Vaya, lado\nequivocado.{DONE}",
  ["_ReflectGainedArmorText"] = "¡{USER}\nganó armadura!{PROMPT}",
  ["_RegainedHealthText"] = "¡{USER}\nrecuperó salud!{PROMPT}",
  ["_ReleaseWhichMonText"] = "¿Qué POKéMON\nliberas?{DONE}",
  ["_RepelWoreOffText"] = "El efecto del\nREPEL se acabó.{DONE}",
  ["_RequireCoinCaseText"] = "¡Hace falta un\nMONEDERO!{DONE}",
  ["_RestorePPWhichTechniqueText"] = "¿De qué técnica\nrestauras los PP?{DONE}",
  ["_ReviveText"] = "¡{RAM:wNameBuffer}\nse revitalizó!{DONE}",
  ["_RhydonDexEntry"] = "Protegido por una\npiel como una\narmadura, puede\12vivir en lava\nfundida a 3600\ngrados",
  ["_RhyhornDexEntry"] = "Sus enormes huesos\nson 1000 veces más\nduros que los\12humanos. Puede\nmandar un remolque\npor los aires",
  ["_Rival1WinText"] = "{RIVAL}: ¡Sí!\n¿Soy genial o\11qué?{PROMPT}",
  ["_RivalDefeatedText"] = "¡NO!\n¡No puede ser!\11¡Has vencido a\11mi mejor equipo!\12¿Después de todo\nlo que me costó\11ser campeón de la\11LIGA?\12¿Mi reinado ha\nterminado ya?\11¡No es justo!{PROMPT}",
  ["_RivalVictoryText"] = "¡Jajaja!\n¡He ganado, he\11ganado!\12¡Soy demasiado\nbueno para ti,\11{PLAYER}!\12¡Lo hiciste bien\nsolo con llegar\11hasta mí, {RIVAL},\11el genio POKéMON!\12¡Buen intento,\nperdedor! ¡Jajaja!{PROMPT}",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "¡Vi un MACHOP en\neste túnel!{DONE}",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "¡Aah! ¡No intentes\nnada raro en la\11oscuridad!{DONE}",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "¡Estaba\ndemasiado oscuro!{PROMPT}",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "¡Parecías mono e\ninofensivo!{DONE}",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "¡He llegado hasta\naquí por los\11POKéMON!{DONE}",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "¡Me he\nquedado sin\11POKéMON!{PROMPT}",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "¡Uf! ¡Ahora estoy\ntoda sudada!{DONE}",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "¡Tienes POKéMON!\n¡Empecemos!{DONE}",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "¡Juegas\nduro!{PROMPT}",
  ["_RockTunnel1FHiker1AfterBattleText"] = "¡Cuidado con\nONIX! ¡Puede\11estrujarte!{DONE}",
  ["_RockTunnel1FHiker1BattleText"] = "¡Este túnel es\nmuy largo, crío!{DONE}",
  ["_RockTunnel1FHiker1EndBattleText"] = "¡Jo!\n¡Ganas tú!{PROMPT}",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Ese POKéMON\ndormido de la RUTA\1112 me obligó a\11dar este rodeo.{DONE}",
  ["_RockTunnel1FHiker2BattleText"] = "Mmm. A lo mejor\nestoy perdido\11aquí...{DONE}",
  ["_RockTunnel1FHiker2EndBattleText"] = "¡Calma!\n¿Qué estoy\11haciendo? ¿Por\11dónde se sale?{PROMPT}",
  ["_RockTunnel1FHiker3AfterBattleText"] = "¡Tienes talento\nde suficiente\11para hacer\11senderismo!{DONE}",
  ["_RockTunnel1FHiker3BattleText"] = "¡Los de fuera\ncomo tú deberíais\11mostrarme algo de\11respeto!{DONE}",
  ["_RockTunnel1FHiker3EndBattleText"] = "¡Me rindo!{PROMPT}",
  ["_RockTunnel1FSignText"] = "TÚNEL ROCA\nCIUDAD CELESTE -\11PUEBLO LAVANDA{DONE}",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "En fin, ¡ya\ncogeré un ZUBAT\11por el camino!{DONE}",
  ["_RockTunnel1FSuperNerdBattleText"] = "¡Combate POKéMON!\n¡Listos, ya!{DONE}",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "¡Fin de\nla partida!{PROMPT}",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "¡Quiero irme a \ncasa!{DONE}",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "Los senderistas\ndejan ramitas\11como marcas del\11camino.{DONE}",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "¡Ohhh!\n¡Hice lo que\11pude!{PROMPT}",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "¡Me gustan los\nPOKéMON pequeñi-\11tos, los grandes\11dan miedo!{DONE}",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "No vengo mucho\npor aquí, pero\11lucharé contigo.{DONE}",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "¡Oh!\n¡He perdido!{PROMPT}",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "¡Voy a por la\nfuerza porque\11odio pensar!{DONE}",
  ["_RockTunnelB1FHiker1BattleText"] = "¡Jajaja! ¿Puedes\ncon mi fuerza?{DONE}",
  ["_RockTunnelB1FHiker1EndBattleText"] = "¡Vaya!\n¡Me han superado\11en músculo!{PROMPT}",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "En las montañas\nsuelen encontrarse\11POKéMON de tipo\11roca.{DONE}",
  ["_RockTunnelB1FHiker2BattleText"] = "¡Mis técnicas\nPOKéMON te harán\11llorar!{DONE}",
  ["_RockTunnelB1FHiker2EndBattleText"] = "¡Me rindo!\n¡Eres mejor\11técnico!{PROMPT}",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "¡Criaré mis\nPOKéMON para\11ganar a los\11tuyos, crío!{DONE}",
  ["_RockTunnelB1FHiker3BattleText"] = "¡Dame con todo\nlo que tengas!{DONE}",
  ["_RockTunnelB1FHiker3EndBattleText"] = "¡Disparé\ny fallé!{PROMPT}",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Cuando termines\ntu POKéDEX, ¿me\11la das?{DONE}",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "¿Tienes una\nPOKéDEX?\11¡Yo también\11quiero una!{DONE}",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "¡Jo!\n¡Qué envidia!{PROMPT}",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Los cosplayers se\ndisfrazan de\11POKéMON por\11diversión.{DONE}",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "¿Sabes lo que son\nlos cosplayers?{DONE}",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Bueno,\npues eso.{PROMPT}",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Soy artista, no\nluchador.{DONE}",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Dibujo POKéMON\ncuando estoy en\11casa.{DONE}",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "¡Uf!\n¡Estoy agotado!{PROMPT}",
  ["_RockTunnelPokecenterFisherText"] = "¡Vendí una PEPITA\ninútil por ₽5000!{DONE}",
  ["_RockTunnelPokecenterGentlemanText"] = "¡Los tipos\nelementales de los\11POKéMON los hacen\11más fuertes que\11unos tipos y más\11débiles que otros!{DONE}",
  ["_RockTunnelPokecenterGuyText"] = "¡He oído que hay\nFANTASMAS que\11rondan PUEBLO\11LAVANDA!{DONE}",
  ["_RocketHide3AfterBattleText3"] = "¡Adelante, ve!\n¡Pero necesitas\11la LLAVE ASCENSOR\11para usar el\11ascensor!{DONE}",
  ["_RocketHideout3BattleText"] = "¡Nos avisaron de\narriba de que\11venías!{DONE}",
  ["_RocketHideout3EndBattleText3"] = "¿Qué?\n¿He perdido? ¡No!{PROMPT}",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "¿Estás faltando al\nrespeto al TEAM\11ROCKET?{DONE}",
  ["_RocketHideoutB1FRocket1BattleText"] = "¿Quién eres? ¿Cómo\nhas llegado aquí?{DONE}",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "¡Ay!\n¡Vencido!{PROMPT}",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "¡No te vas a\nsalir con la\11tuya, mocoso!{DONE}",
