  ["_Route15Beauty2BattleText"] = "¡Crío POKéMON\nporque vivo sola!{DONE}",
  ["_Route15Beauty2EndBattleText"] = "¡Yo no\npedí esto!{PROMPT}",
  ["_Route15Biker1AfterBattleText"] = "¡Solo se vive una\nvez, así que vivo\11como un forajido!\11¡EL TEAM ROCKET\11MANDA!{DONE}",
  ["_Route15Biker1BattleText"] = "¡Eh, crío! ¡Venga!\n¡Acabo de\11pillarlas!{DONE}",
  ["_Route15Biker1EndBattleText"] = "¿Por qué\nno?{PROMPT}",
  ["_Route15Biker2AfterBattleText"] = "¡Era broma lo\ndel dinero!{DONE}",
  ["_Route15Biker2BattleText"] = "¡Suéltame toda\ntu pasta cuando\11pierdas contra\11mí, crío!{DONE}",
  ["_Route15Biker2EndBattleText"] = "¡Eso no\npuede ser verdad!{PROMPT}",
  ["_Route15CooltrainerF1AfterBattleText"] = "No puedes cambiar\nel mote de ningún\11POKéMON que\11consigas en un\11intercambio.\12Solo puede el\nEntrenador\11Original.{DONE}",
  ["_Route15CooltrainerF1BattleText"] = "¡Deja que pruebe\nel POKéMON que\11acabo de conseguir\11en un intercambio!{DONE}",
  ["_Route15CooltrainerF1EndBattleText"] = "¡No es\nsuficiente!{PROMPT}",
  ["_Route15CooltrainerF2AfterBattleText"] = "¡Los MOTERISTAS\nme dan miedo,\11parecen tan feos\11y malos!{DONE}",
  ["_Route15CooltrainerF2BattleText"] = "Pareces amable,\nasí que creo que\11puedo ganarte.{DONE}",
  ["_Route15CooltrainerF2EndBattleText"] = "¡No,\nqué error!{PROMPT}",
  ["_Route15CooltrainerF3AfterBattleText"] = "¡Intercambio\nPOKéMON con mis\11amigos!{DONE}",
  ["_Route15CooltrainerF3BattleText"] = "¿Qué mola?\n¡Intercambiar\11POKéMON!{DONE}",
  ["_Route15CooltrainerF3EndBattleText"] = "¡He dicho\nque intercambio!{PROMPT}",
  ["_Route15CooltrainerF4AfterBattleText"] = "Iré a entrenar\ncon gente más\11débil.{DONE}",
  ["_Route15CooltrainerF4BattleText"] = "¿Quieres jugar\ncon mis POKéMON?{DONE}",
  ["_Route15CooltrainerF4EndBattleText"] = "¡Fui\ndemasiado\11impaciente!{PROMPT}",
  ["_Route15CooltrainerM1AfterBattleText"] = "Quizá no estoy\nhecho para los\11combates.{DONE}",
  ["_Route15CooltrainerM1BattleText"] = "¡Cuando silbo,\npuedo llamar a\11POKéMON pájaro!{DONE}",
  ["_Route15CooltrainerM1EndBattleText"] = "¡Ay!\n¡Qué tragedia!{PROMPT}",
  ["_Route15CooltrainerM2AfterBattleText"] = "¿Sabías que\nataques como\11TERREMOTO no\11afectan a las\11aves?{DONE}",
  ["_Route15CooltrainerM2BattleText"] = "¿Mmm? ¡Mis aves\ntiemblan! Eres\11bueno, ¿verdad?{DONE}",
  ["_Route15CooltrainerM2EndBattleText"] = "¡Justo\ncomo pensaba!{PROMPT}",
  ["_Route15Gate1FGuardText"] = "¿Estás haciendo\nuna POKéDEX?\12El AYUDANTE del\nPROF. OAK pasó\11por aquí.{DONE}",
  ["_Route15Gate2FBinocularsText"] = "Miraste por los\nprismáticos.\12¡Parece una isla\npequeña!{DONE}",
  ["_Route15Gate2FOaksAideExpAllText"] = "El REPARTE EXP da\npuntos de EXP a\11todos los POKéMON\11que llevas,\11aunque no\11combatan.\12Eso sí, reduce la\ncantidad de EXP\11de cada POKéMON.\12Si no lo\nnecesitas,\11deberías\11guardarlo por PC.{DONE}",
  ["_Route15SignText"] = "RUTA 15\nAl oeste, CIUDAD\11FUCSIA{DONE}",
  ["_Route15UpstairsBinocularsText"] = "Miraste por los\nprismáticos...\12Un ave grande y\nreluciente vuela\11hacia el mar.{DONE}",
  ["_Route16Biker1AfterBattleText"] = "Nos gusta pasar\nel rato aquí,\11¿pasa algo?{DONE}",
  ["_Route16Biker1BattleText"] = "¿Qué quieres?{DONE}",
  ["_Route16Biker1EndBattleText"] = "¡Ni se te\nocurra reírte!{PROMPT}",
  ["_Route16Biker2AfterBattleText"] = "¡Olvídalo, ¿quién\nquiere tu BICI?!{DONE}",
  ["_Route16Biker2BattleText"] = "¡Bonita BICI!\n¡Dámela!{DONE}",
  ["_Route16Biker2EndBattleText"] = "¡Fuera de\ncombate!{PROMPT}",
  ["_Route16Biker3AfterBattleText"] = "¡Odio perder!\n¡Aléjate de mí!{DONE}",
  ["_Route16Biker3BattleText"] = "¡Sal a jugar,\nratoncito!{DONE}",
  ["_Route16Biker3EndBattleText"] = "¡Serás\nratita!{PROMPT}",
  ["_Route16Biker4AfterBattleText"] = "También se puede\nllegar a FUCSIA\11desde CARMÍN por\11una carretera de\11la costa.{DONE}",
  ["_Route16Biker4EndBattleText"] = "¡Kabum!{PROMPT}",
  ["_Route16Biker5AfterBattleText"] = "¡Me gustan mis\nPOKéMON feroces!\11¡Despedazan a los\11enemigos!{DONE}",
  ["_Route16Biker5BattleText"] = "¡Tengo hambre y\nmala leche!{DONE}",
  ["_Route16Biker5EndBattleText"] = "¡Mal,\nmal, mal!{PROMPT}",
  ["_Route16Biker6AfterBattleText"] = "¡Me gusta\nfastidiar a la\11gente con mis\11POKéMON\11despiadados!{DONE}",
  ["_Route16Biker6BattleText"] = "¡Claro, voy!{DONE}",
