  ["_SlowbroDexEntry"] = "Se dice que el\nSHELLDER prendido\nde la cola de\12SLOWPOKE se\nalimenta de las\nsobras del anfitrión",
  ["_SlowpokeDexEntry"] = "Increíblemente\nlento y bobo. Tarda\n5 segundos en\12sentir el dolor\ncuando lo atacan",
  ["_SnorlaxDexEntry"] = "Muy holgazán. Solo\ncome y duerme.\nCuanto más engorda\12su cuerpo redondo,\nmás perezoso se\nvuelve",
  ["_SoYouWantPrizeText"] = "",
  ["_SorryNeedMoreCoinsText"] = "",
  ["_SpearowDexEntry"] = "Come insectos en\nzonas de hierba.\nDebe agitar sus\12cortas alas a gran\nvelocidad para\nseguir en el aire",
  ["_SquirtleDexEntry"] = "Tras nacer, su lomo\nse hincha y endurece\nhasta formar un\12caparazón. Escupe\nespuma con fuerza\npor la boca",
  ["_StarmieDexEntry"] = "Su núcleo central\nbrilla con los\nsiete colores del\12arcoíris. Hay quien\nvalora el núcleo\ncomo una gema",
  ["_StartSlotMachineText"] = "",
  ["_StartedSleepingEffect"] = "",
  ["_StaryuDexEntry"] = "POKéMON enigmático\nque puede regenerar\nsin esfuerzo\12cualquier apéndice\nque pierda en\ncombate",
